            <Converter />
          </DraggableWindow>

          <DraggableWindow id="compressor" title="Compressor" defaultWidth={800} defaultHeight={600}>
            <Compressor />
          </DraggableWindow>

          <DraggableWindow id="exchange" title="Global Exchange" defaultWidth={900} defaultHeight={650}>
            <Exchange />
          </DraggableWindow>

