            <MusicPlayer />
          </DraggableWindow>

          <DraggableWindow id="game2048" title="2048" defaultWidth={600} defaultHeight={750}>
            <Game2048 />
          </DraggableWindow>

          <DraggableWindow id="tictactoe" title="Tic Tac Toe" defaultWidth={500} defaultHeight={650}>
            <TicTacToe />
          </DraggableWindow>

