'use client';
import { useWindowStore } from '@/store/useWindowStore';
import { useSettingsStore } from '@/store/useSettingsStore';
import { motion, AnimatePresence } from 'framer-motion';
import { getAllApps } from '@/data/apps';
import { Search } from 'lucide-react';
import { useState } from 'react';

export default function Launchpad() {
  const { isLaunchpadOpen, closeLaunchpad, openApp } = useWindowStore();
  const { themeMode } = useSettingsStore();
  const [searchQuery, setSearchQuery] = useState('');

  const isLight = themeMode === 'light';
  const apps = getAllApps(isLight).filter(app => app.title.toLowerCase().includes(searchQuery.toLowerCase()));

  // Prevent clicks inside the launchpad content from closing it
  const handleContentClick = (e: React.MouseEvent) => {
    e.stopPropagation();
  };

  const handleAppClick = (id: any, title: string) => {
    openApp(id, title);
    closeLaunchpad();
    setSearchQuery('');
  };

  return (
    <AnimatePresence>
      {isLaunchpadOpen && (
        <motion.div
          initial={{ opacity: 0, scale: 1.1 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 1.1 }}
          transition={{ duration: 0.3, ease: [0.2, 0.8, 0.2, 1] }}
          className={`absolute inset-0 z-[9998] flex flex-col items-center pt-24 px-10 pb-20 overflow-hidden backdrop-blur-2xl ${
            isLight ? 'bg-white/40' : 'bg-black/40'
          }`}
          onClick={() => {
            closeLaunchpad();
            setSearchQuery('');
          }}
        >
          {/* Optional Search Bar mimicking macOS */}
          <div 
            className="w-full max-w-sm mb-12 relative"
            onClick={handleContentClick}
          >
            <div className={`absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>
              <Search className="h-4 w-4" />
            </div>
            <input
              type="text"
              placeholder="Search"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className={`block w-full pl-10 pr-3 py-2 border-transparent rounded-xl text-center text-sm focus:outline-none focus:ring-2 transition-all ${
                isLight 
                  ? 'bg-black/10 text-slate-800 placeholder-slate-500 focus:bg-white focus:ring-black/20' 
                  : 'bg-white/10 text-slate-200 placeholder-slate-400 focus:bg-white/20 focus:ring-white/30'
              }`}
            />
          </div>

          <div 
            className="w-full max-w-5xl mx-auto grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-x-4 gap-y-12"
            onClick={handleContentClick}
          >
            {apps.map((app) => (
              <motion.div
                key={app.id}
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
                className="flex flex-col items-center gap-2 cursor-pointer group"
                onClick={() => handleAppClick(app.id, app.title)}
              >
                <div className={`w-16 h-16 sm:w-20 sm:h-20 rounded-2xl flex items-center justify-center transition-transform shadow-lg ${
                  isLight ? 'bg-white/60 border border-white/80' : 'bg-white/10 border border-white/20'
                }`}>
                  <img 
                    src={app.iconUrl} 
                    alt={app.title} 
                    className="w-12 h-12 sm:w-14 sm:h-14 object-contain drop-shadow-lg transition-transform group-hover:scale-105"
                    style={{ transform: app.scale ? 'scale(' + app.scale + ')' : 'scale(1)' }}
                    onError={(e) => {
                      e.currentTarget.style.display = 'none';
                    }}
                  />
                </div>
                <span className={`text-xs sm:text-sm font-medium text-center truncate w-full px-1 drop-shadow-sm ${
                  isLight ? 'text-slate-800' : 'text-slate-100'
                }`}>
                  {app.title}
                </span>
              </motion.div>
            ))}
          </div>

          {apps.length === 0 && (
            <div className={`mt-20 text-lg ${isLight ? 'text-slate-600' : 'text-slate-400'}`}>
              No applications found
            </div>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

src/components/MenuBar.tsx.content:
'use client';
import { useSettingsStore } from '@/store/useSettingsStore';
import { useWindowStore } from '@/store/useWindowStore';
import { Wifi, BatteryMedium, Search, Command, Bot, Loader2 } from 'lucide-react';
import { useEffect, useState } from 'react';

const TIMEZONES = [
  { label: 'Local Time', value: 'Local' },
  { label: 'New York (EST)', value: 'America/New_York' },
  { label: 'London (GMT)', value: 'Europe/London' },
  { label: 'Dubai (GST)', value: 'Asia/Dubai' },
  { label: 'India (IST)', value: 'Asia/Kolkata' },
  { label: 'Tokyo (JST)', value: 'Asia/Tokyo' },
  { label: 'Sydney (AEST)', value: 'Australia/Sydney' },
];

export default function MenuBar() {
  const { themeMode } = useSettingsStore();
  const { windows, highestZIndex, openApp } = useWindowStore();
  const [time, setTime] = useState<string>('');
  const [dateStr, setDateStr] = useState<string>('');
  const [now, setNow] = useState<Date | null>(null);
  const [mounted, setMounted] = useState(false);
  const [activeMenu, setActiveMenu] = useState<'wifi' | 'battery' | 'clock' | null>(null);
  const [timezone, setTimezone] = useState<string>('Local');
  const [batteryInfo, setBatteryInfo] = useState<{ level: number; charging: boolean } | null>(null);
  const [isOnline, setIsOnline] = useState(true);

  const [speedTestState, setSpeedTestState] = useState<'idle' | 'testing' | 'done'>('idle');
  const [speedResult, setSpeedResult] = useState({ down: 0, up: 0 });

  const runSpeedTest = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (speedTestState === 'testing') return;
    setSpeedTestState('testing');

    setTimeout(() => {
      setSpeedResult({
        down: Math.floor(Math.random() * 250) + 100,
        up: Math.floor(Math.random() * 80) + 20
      });
      setSpeedTestState('done');
      setTimeout(() => setSpeedTestState('idle'), 5000);
    }, 2000);
  };

  const isLight = themeMode === 'light';

  useEffect(() => {
    setMounted(true);
    const updateTime = () => {
      const currentDate = new Date();
      setNow(currentDate);
      setTime(currentDate.toLocaleTimeString([], { weekday: 'short', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }));
      setDateStr(currentDate.toLocaleDateString([], { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }));
    };
    updateTime();
    const interval = setInterval(updateTime, 1000);

    // Battery
    if ('getBattery' in navigator) {
      (navigator as any).getBattery().then((battery: any) => {
        setBatteryInfo({ level: Math.round(battery.level * 100), charging: battery.charging });
        battery.addEventListener('levelchange', () => {
          setBatteryInfo((prev: any) => ({ ...prev, level: Math.round(battery.level * 100) }));
        });
        battery.addEventListener('chargingchange', () => {
          setBatteryInfo((prev: any) => ({ ...prev, charging: battery.charging }));
        });
      });
    } else {
      setBatteryInfo({ level: 100, charging: false });
    }

    // Network
    setIsOnline(navigator.onLine);
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      clearInterval(interval);
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  if (!mounted) return null;

  // Determine active app name for the menu bar
  let activeAppName = 'Portfolio OS';
  const openWindows = Object.values(windows).filter(w => w.isOpen && !w.isMinimized);
  if (openWindows.length > 0) {
    const activeWindow = openWindows.find(w => w.zIndex === highestZIndex);
    if (activeWindow) {
      activeAppName = activeWindow.title;
    }
  }

  let displayNow = now;
  if (now && timezone !== 'Local') {
    try {
      displayNow = new Date(now.toLocaleString("en-US", { timeZone: timezone }));
    } catch (e) {
      displayNow = now;
    }
  }

  return (
    <div className={`w-full h-7 flex items-center justify-between px-3 select-none text-sm font-medium backdrop-blur-md z-[9999] relative
      ${isLight ? 'bg-white/30 text-slate-900 border-b border-white/40' : 'bg-black/30 text-slate-200 border-b border-white/10'}`}
    >
      <div className="flex items-center space-x-4">
        <div 
          className="flex items-center gap-1.5 cursor-pointer opacity-80 hover:opacity-100"
          onClick={() => useWindowStore.getState().toggleLaunchpad()}
        >
          <Command size={14} />
        </div>
        <div className="font-bold tracking-wide cursor-pointer">{activeAppName}</div>
        <div className="hidden sm:flex space-x-4 opacity-80">
          <span className="cursor-pointer hover:opacity-100" onClick={() => { openApp('resume', 'Resume.pdf'); setTimeout(() => window.dispatchEvent(new CustomEvent('navigate-resume', { detail: 'summary' })), 150); }}>About</span>
          <span className="cursor-pointer hover:opacity-100" onClick={() => { openApp('resume', 'Resume.pdf'); setTimeout(() => window.dispatchEvent(new CustomEvent('navigate-resume', { detail: 'projects' })), 150); }}>Projects</span>
          <span className="cursor-pointer hover:opacity-100" onClick={() => { openApp('resume', 'Resume.pdf'); setTimeout(() => window.dispatchEvent(new CustomEvent('navigate-resume', { detail: 'experience' })), 150); }}>Experience</span>
          <span className="cursor-pointer hover:opacity-100" onClick={() => { openApp('resume', 'Resume.pdf'); setTimeout(() => window.dispatchEvent(new CustomEvent('navigate-resume', { detail: 'skills' })), 150); }}>Skills</span>
          <span className="cursor-pointer hover:opacity-100" onClick={() => { openApp('resume', 'Resume.pdf'); setTimeout(() => window.dispatchEvent(new CustomEvent('navigate-resume', { detail: 'contact' })), 150); }}>Contact</span>
          <span className="cursor-pointer hover:opacity-100 font-semibold text-emerald-400" onClick={() => openApp('chatbot', 'Virtual Rohit')}>Virtual Rohit</span>
          <span className="cursor-pointer hover:opacity-100" onClick={() => openApp('help', 'Help Center')}>Help</span>
        </div>
      </div>

      <div className="flex items-center space-x-4 opacity-90">
        <div className="flex items-center space-x-3 relative">
          {/* Wi-Fi Icon */}
          <div className="relative">
            <Wifi 
              size={14} 
              className={`cursor-pointer ${!isOnline ? 'opacity-50' : ''}`}
              onClick={() => setActiveMenu(activeMenu === 'wifi' ? null : 'wifi')} 
            />
            {activeMenu === 'wifi' && (
              <div className={`absolute top-full right-0 mt-2 w-48 p-2 rounded-xl shadow-xl border text-sm backdrop-blur-3xl z-50
                ${isLight ? 'bg-white/80 border-slate-200 text-slate-800' : 'bg-[#1e1e1e]/90 border-slate-800 text-slate-200'}`}>
                <div className="flex flex-col space-y-2">
                  <div className="font-semibold px-2 py-1 border-b border-white/10">Network</div>
                  <div className="px-2 py-1 rounded-md flex items-center justify-between">
                    <span>Status</span>
                    <div className="flex items-center gap-1.5">
                      {isOnline ? <span className="text-emerald-500 font-medium">Online</span> : <span className="text-red-500 font-medium">Offline</span>}
                      {isOnline && <Wifi size={14} className="text-emerald-500" />}
                    </div>
                  </div>

                  {isOnline && (
                    <div className="px-2 pb-1">
                      {speedTestState === 'idle' && (
                        <button 
                          onClick={runSpeedTest}
                          className="w-full py-1.5 bg-blue-500 hover:bg-blue-600 text-white rounded-md text-xs font-semibold transition-colors flex items-center justify-center gap-2"
                        >
                          Run Speed Test
                        </button>
                      )}

                      {speedTestState === 'testing' && (
                        <div className="w-full py-1.5 bg-slate-100 dark:bg-white/10 text-slate-600 dark:text-slate-300 rounded-md text-xs font-medium flex items-center justify-center gap-2">
                          <Loader2 size={12} className="animate-spin" /> Testing...
                        </div>
                      )}

                      {speedTestState === 'done' && (
                        <div className="w-full p-2 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-md text-xs flex flex-col gap-1">
                          <div className="flex justify-between items-center">
                            <span className="text-slate-500 dark:text-slate-400">Download</span>
                            <span className="font-bold text-emerald-500">{speedResult.down} Mbps</span>
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="text-slate-500 dark:text-slate-400">Upload</span>
                            <span className="font-bold text-blue-500">{speedResult.up} Mbps</span>
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Battery Icon */}
          <div className="relative">
            <BatteryMedium 
              size={14} 
              className="cursor-pointer"
              onClick={() => setActiveMenu(activeMenu === 'battery' ? null : 'battery')} 
            />
            {activeMenu === 'battery' && (
              <div className={`absolute top-full right-0 mt-2 w-48 p-2 rounded-xl shadow-xl border text-sm backdrop-blur-3xl z-50
                ${isLight ? 'bg-white/80 border-slate-200 text-slate-800' : 'bg-[#1e1e1e]/90 border-slate-800 text-slate-200'}`}>
                <div className="flex flex-col space-y-1">
                  <div className="font-semibold px-2 py-1">Battery</div>
                  <div className="px-2 py-1 rounded-md flex items-center justify-between">
                    <span>Power Source</span>
                    <span className="text-xs text-slate-500">{batteryInfo?.charging ? 'Power Adapter' : 'Battery'}</span>
                  </div>
                  <div className="px-2 py-1 rounded-md flex items-center justify-between">
                    <span>Level</span>
                    <span className="font-medium">{batteryInfo?.level || 100}%</span>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
        <div className="relative flex items-center">
          <span 
            className="text-xs cursor-pointer"
            onClick={() => setActiveMenu(activeMenu === 'clock' ? null : 'clock')}
          >
            {time}
          </span>
          {activeMenu === 'clock' && displayNow && (
            <div className={`absolute top-full right-0 mt-2 w-72 p-8 rounded-3xl shadow-2xl z-50
              ${isLight ? 'bg-[#f0f2f5] border border-white/50' : 'bg-[#222327] border border-black/50'}`}>
              <div className="flex flex-col items-center justify-center space-y-10">
                {/* Neumorphic Clock */}
                <div className={`relative w-48 h-48 rounded-full flex items-center justify-center
                  ${isLight 
                    ? 'bg-[#f0f2f5] shadow-[-10px_-10px_20px_#ffffff,10px_10px_20px_#d1d5db]' 
                    : 'bg-[#222327] shadow-[-8px_-8px_16px_#2c2d33,8px_8px_16px_#18191b]'}`}>
                  <svg viewBox="0 0 100 100" className="w-full h-full">
                    {/* 4 Ticks */}
                    <line x1="50" y1="12" x2="50" y2="18" className={`stroke-[1] ${isLight ? 'stroke-slate-400' : 'stroke-slate-500'}`} />
                    <line x1="50" y1="88" x2="50" y2="82" className={`stroke-[1] ${isLight ? 'stroke-slate-400' : 'stroke-slate-500'}`} />
                    <line x1="12" y1="50" x2="18" y2="50" className={`stroke-[1] ${isLight ? 'stroke-slate-400' : 'stroke-slate-500'}`} />
                    <line x1="88" y1="50" x2="82" y2="50" className={`stroke-[1] ${isLight ? 'stroke-slate-400' : 'stroke-slate-500'}`} />

                    {/* Hour Hand */}
                    <line 
                      x1="50" y1="50" x2="50" y2="28"
                      transform={`rotate(${(displayNow.getHours() % 12) * 30 + displayNow.getMinutes() * 0.5} 50 50)`}
                      className={`stroke-[3.5] ${isLight ? 'stroke-[#474c5c]' : 'stroke-[#c1c4cd]'}`}
                      strokeLinecap="round"
                    />

                    {/* Minute Hand */}
                    <line 
                      x1="50" y1="50" x2="50" y2="16"
                      transform={`rotate(${displayNow.getMinutes() * 6} 50 50)`}
                      className={`stroke-[2.5] ${isLight ? 'stroke-[#474c5c]' : 'stroke-[#c1c4cd]'}`}
                      strokeLinecap="round"
                    />

                    {/* Second Hand */}
                    <line 
                      x1="50" y1="58" x2="50" y2="16"
                      transform={`rotate(${displayNow.getSeconds() * 6} 50 50)`}
                      className="stroke-[#375ee3] stroke-[1.5]"
                      strokeLinecap="round"
                    />

                    {/* Center Pin */}
                    <circle cx="50" cy="50" r="3" className="fill-[#375ee3]" />
                  </svg>
                </div>

                {/* Digital Time & Date */}
                <div className="flex flex-col items-center w-full">
                  <div className="flex items-start">
                    <span className={`text-6xl font-medium tracking-tight leading-none ${isLight ? 'text-[#1a1b26]' : 'text-white'}`}>
                      {`${displayNow.getHours() % 12 || 12}:${displayNow.getMinutes().toString().padStart(2, '0')}`}
                    </span>
                    <span className={`text-base font-semibold mt-1 ml-1 ${isLight ? 'text-[#1a1b26]' : 'text-white'}`}>
                      {displayNow.getHours() >= 12 ? 'PM' : 'AM'}
                    </span>
                  </div>
                  <div className={`text-base font-medium mt-3 ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>
                    {displayNow.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}
                  </div>

                  <div className="w-full mt-8">
                    <select 
                      className={`w-full outline-none text-sm font-medium py-2 px-3 rounded-xl cursor-pointer transition-colors appearance-none text-center
                        ${isLight 
                          ? 'bg-[#e4e6e9] hover:bg-[#d9dbde] text-[#1a1b26]' 
                          : 'bg-[#2c2d33] hover:bg-[#32333a] text-white'}`}
                      value={timezone}
                      onChange={(e) => setTimezone(e.target.value)}
                    >
                      {TIMEZONES.map(tz => (
                        <option key={tz.value} value={tz.value}>{tz.label}</option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

src/components/Taskbar.tsx.content:
'use client';
import { useWindowStore, AppId } from '@/store/useWindowStore';
import { useSettingsStore } from '@/store/useSettingsStore';
import { Terminal, FileText, Briefcase, Video, Settings as SettingsIcon, Code2, Languages, Bot } from 'lucide-react';
import { useEffect, useState, useRef } from 'react';
import { motion, useMotionValue, useSpring, useTransform, MotionValue, AnimatePresence } from 'framer-motion';
import { ChevronDown, ChevronUp } from 'lucide-react';
import { getTaskbarApps } from '@/data/apps';

export default function Taskbar() {
  const { windows, openApp, minimizeApp, focusApp, highestZIndex } = useWindowStore();
  const { themeMode, accentColor, taskbarVisible, toggleTaskbar } = useSettingsStore();
  const [mounted, setMounted] = useState(false);

  const isLight = themeMode === 'light';
  const apps = getTaskbarApps(isLight);

  const mouseX = useMotionValue(Infinity);

  useEffect(() => {
    setMounted(true);
  }, []);

  const handleAppClick = (id: AppId, title: string) => {
    if (id === 'launchpad') {
      useWindowStore.getState().toggleLaunchpad();
      return;
    }

    const win = windows[id];
    if (!win.isOpen) {
      openApp(id, title);
    } else if (win.isMinimized) {
      focusApp(id);
    } else if (win.zIndex === highestZIndex) {
      minimizeApp(id);
    } else {
      focusApp(id);
    }
  };

  if (!mounted) return null;

  return (
    <>
      <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-[40]">
        <AnimatePresence>
          {taskbarVisible && (
            <motion.div 
              initial={{ y: 150, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: 150, opacity: 0, scale: 0.9 }}
              transition={{ type: 'spring', damping: 25, stiffness: 200 }}
              onMouseMove={(e) => mouseX.set(e.pageX)}
              onMouseLeave={() => mouseX.set(Infinity)}
              className={`flex items-end gap-2 px-3 pb-2 h-[72px] rounded-2xl backdrop-blur-3xl border shadow-2xl transition-colors
                ${isLight ? 'bg-white/40 border-white/60' : 'bg-black/40 border-white/10'}`}
            >
              {apps.map((app) => {
                const win = windows[app.id];
                const isOpen = win?.isOpen || false;
                const isFocused = isOpen && win.zIndex === highestZIndex && !win.isMinimized;

                return (
                  <DockIcon 
                    key={app.id} 
                    mouseX={mouseX} 
                    app={app}
                    isOpen={isOpen}
                    isFocused={isFocused}
                    isLight={isLight}
                    onClick={() => handleAppClick(app.id, app.title)}
                  />
                );
              })}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Taskbar Toggle Button */}
      <div className="absolute bottom-0 left-1/2 -translate-x-1/2 z-[50] w-full h-4 flex justify-center items-end group">
        <button 
          onClick={toggleTaskbar}
          className={`w-12 h-5 rounded-t-full backdrop-blur-md border border-b-0 flex items-center justify-center transition-all opacity-0 group-hover:opacity-100 hover:h-6 hover:w-16
            ${isLight ? 'bg-white/60 border-white/80 text-slate-700' : 'bg-white/10 border-white/20 text-white/70'}`}
        >
          {taskbarVisible ? <ChevronDown size={14} /> : <ChevronUp size={14} />}
        </button>
      </div>
    </>
  );
}

// Separate component for each Icon to calculate its own physics based on distance
function DockIcon({ 
  mouseX, 
  app, 
  isOpen, 
  isFocused, 
  isLight,
  onClick 
}: { 
  mouseX: MotionValue; 
  app: any; 
  isOpen: boolean; 
  isFocused: boolean; 
  isLight: boolean;
  onClick: () => void;
}) {
  const ref = useRef<HTMLButtonElement>(null);

  // Calculate distance between mouse X and icon center X
  const distance = useTransform(mouseX, (val) => {
    const bounds = ref.current?.getBoundingClientRect() ?? { x: 0, width: 0 };
    return val - bounds.x - bounds.width / 2;
  });

  // Map distance to size (closer = bigger)
  const widthSync = useTransform(distance, [-150, 0, 150], [50, 90, 50]);
  const width = useSpring(widthSync, { mass: 0.1, stiffness: 150, damping: 12 });

  return (
    <div className="relative flex flex-col items-center justify-end h-full">
      <motion.button
        ref={ref}
        style={{ width, height: width }}
        whileTap={{ scale: 0.95 }}
        onClick={onClick}
        className="cursor-pointer relative group flex items-end justify-center focus:outline-none"
      >
        {/* Real App Icon */}
        <img 
          src={app.iconUrl} 
          alt={app.title}
          className="w-full h-full object-contain drop-shadow-xl"
          style={app.scale ? { transform: `scale(${app.scale})` } : {}}
        />

        {/* Tooltip */}
        <div className={`absolute -top-14 opacity-0 group-hover:opacity-100 transition-opacity text-sm font-medium px-3 py-1.5 rounded-md backdrop-blur-md pointer-events-none whitespace-nowrap shadow-xl z-50
          ${isLight ? 'bg-white/90 text-slate-800 border border-slate-200' : 'bg-black/70 text-white border border-white/10'}`}>
          {app.title}
        </div>
      </motion.button>

      {/* Active Indicator dot - perfectly aligned at the bottom of the glass pill */}
      <div className="absolute -bottom-1 w-full flex justify-center">
        <div className={`w-1 h-1 rounded-full transition-all ${isOpen ? 'opacity-100' : 'opacity-0'} 
          ${isFocused ? (isLight ? 'bg-slate-800' : 'bg-white shadow-[0_0_8px_rgba(255,255,255,0.8)]') : (isLight ? 'bg-slate-400' : 'bg-white/50')}`} 
        />
      </div>
    </div>
  );
}

src/components/apps/AIAssistant.tsx.content:
'use client';
import { useState, useRef, useEffect } from 'react';
import { useSettingsStore } from '@/store/useSettingsStore';
import { Bot, Send, User, Mic, Sparkles } from 'lucide-react';

interface Message {
  role: 'user' | 'model';
  content: string;
}

export default function AIAssistant() {
  const { themeMode, accentColor } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [messages, setMessages] = useState<Message[]>([
    {
      role: 'model',
      content: "Hi! I'm AI Assistant, your personal guide for this Portfolio OS. I can tell you all about Rohit's work experience, his projects, or how this custom OS works. What would you like to know?"
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  const startListening = () => {
    // @ts-ignore
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice input is not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = true;

    recognition.onstart = () => setIsListening(true);

    recognition.onresult = (event: any) => {
      const transcript = Array.from(event.results)
        .map((result: any) => result[0])
        .map((result: any) => result.transcript)
        .join('');
      setInput(transcript);
    };

    recognition.onerror = (event: any) => {
      if (event.error === 'not-allowed') {
        alert("Microphone access was denied. Please allow microphone access in your browser settings to use voice typing.");
      } else {
        console.warn("Speech recognition error:", event.error);
      }
      setIsListening(false);
    };

    recognition.onend = () => {
      setIsListening(false);
    };

    recognition.start();
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage: Message = { role: 'user', content: input };
    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          // Skip the first initial greeting message from the model
          messages: [...messages.slice(1), userMessage],
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Failed to fetch response');
      }

      setMessages((prev) => [...prev, { role: 'model', content: data.response }]);
    } catch (error: any) {
      console.error('Chat error:', error);
      setMessages((prev) => [
        ...prev,
        { role: 'model', content: `Error: ${error.message}. Please check your API key and connection.` }
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className={`flex flex-col h-full transition-colors ${isLight ? 'bg-slate-50 text-slate-900' : 'bg-[#1e1e1e] text-slate-200'}`}>
      {/* Header */}
      <div className={`flex items-center gap-3 p-4 border-b ${isLight ? 'bg-white border-slate-200' : 'bg-black/20 border-white/10'}`}>
        <div className={`p-2 rounded-xl bg-gradient-to-br ${accentColor} shadow-lg`}>
          <Sparkles className="w-5 h-5 text-white" />
        </div>
        <div>
          <h2 className="font-bold text-lg">AI Assistant</h2>
          <p className={`text-xs font-medium flex items-center gap-1.5 ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
            </span>
            This is a real AI chat bot powered by Google's AI model
          </p>
        </div>
      </div>

      {/* Chat History */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {messages.map((msg, index) => (
          <div key={index} className={`flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : ''}`}>
            {/* Avatar */}
            <div className={`shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${
              msg.role === 'user' 
                ? 'bg-blue-500 text-white' 
                : `bg-gradient-to-br ${accentColor} text-white shadow-md`
            }`}>
              {msg.role === 'user' ? <User size={16} /> : <Bot size={16} />}
            </div>

            {/* Bubble */}
            <div className={`max-w-[80%] rounded-2xl p-4 ${
              msg.role === 'user'
                ? 'bg-blue-500 text-white rounded-tr-sm'
                : `${isLight ? 'bg-white shadow-sm border border-slate-100' : 'bg-[#2d2d2d] border border-white/5'} rounded-tl-sm`
            }`}>
              <p className="whitespace-pre-wrap leading-relaxed text-sm">
                {msg.content}
              </p>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex gap-4">
            <div className={`shrink-0 w-8 h-8 rounded-full flex items-center justify-center bg-gradient-to-br ${accentColor} text-white shadow-md`}>
              <Bot size={16} />
            </div>
            <div className={`rounded-2xl p-4 rounded-tl-sm flex items-center gap-1.5 ${isLight ? 'bg-white shadow-sm border border-slate-100' : 'bg-[#2d2d2d] border border-white/5'}`}>
              <span className="w-2 h-2 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '0ms' }} />
              <span className="w-2 h-2 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '150ms' }} />
              <span className="w-2 h-2 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '300ms' }} />
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className={`p-4 border-t ${isLight ? 'bg-white border-slate-200' : 'bg-black/20 border-white/10'}`}>
        <form onSubmit={handleSubmit} className="relative flex items-center gap-2">
          <div className="relative flex-1">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder={isListening ? "Listening..." : "Ask me anything..."}
              className={`w-full py-3 pl-4 pr-12 rounded-xl border outline-none transition-all ${
                isLight 
                  ? 'bg-slate-50 border-slate-200 focus:border-blue-400 focus:ring-2 focus:ring-blue-100' 
                  : 'bg-[#1e1e1e] border-white/10 focus:border-blue-500 text-white placeholder-slate-500'
              }`}
              disabled={isLoading}
            />
            <button
              type="button"
              onClick={startListening}
              className={`absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-lg transition-colors ${
                isListening 
                  ? 'text-red-500 bg-red-50 dark:bg-red-500/10 animate-pulse' 
                  : 'text-slate-400 hover:text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-500/10'
              }`}
              disabled={isLoading}
            >
              <Mic size={18} />
            </button>
          </div>
          <button
            type="submit"
            disabled={!input.trim() || isLoading}
            className={`p-3 rounded-xl transition-all ${
              !input.trim() || isLoading
                ? 'opacity-50 cursor-not-allowed bg-slate-100 text-slate-400 dark:bg-white/5' 
                : `bg-gradient-to-r ${accentColor} text-white shadow-md hover:shadow-lg hover:opacity-90`
            }`}
          >
            <Send size={18} />
          </button>
        </form>
      </div>
    </div>
  );
}

src/components/apps/ChatBot.tsx.content:
'use client';
import { useState, useRef, useEffect } from 'react';
import { useSettingsStore } from '@/store/useSettingsStore';
import { Bot, Send, User, Mic } from 'lucide-react';

interface Message {
  id: string;
  sender: 'ai' | 'user';
  text: string;
  timestamp: Date;
}

export default function ChatBot() {
  const { themeMode, accentColor } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      sender: 'ai',
      text: "Hi! I'm Virtual Rohit. Ask me anything about Rohit's skills, experience, projects, or education!",
      timestamp: new Date()
    }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);

  const startListening = () => {
    // @ts-ignore
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice input is not supported in this browser.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = true;

    recognition.onstart = () => setIsListening(true);

    recognition.onresult = (event: any) => {
      const transcript = Array.from(event.results)
        .map((result: any) => result[0])
        .map((result: any) => result.transcript)
        .join('');
      setInputValue(transcript);
    };

    recognition.onerror = (event: any) => {
      console.error("Speech recognition error", event.error);
      setIsListening(false);
    };

    recognition.onend = () => {
      setIsListening(false);
    };

    recognition.start();
  };

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const analyzeMessage = (text: string): string => {
    const lower = text.toLowerCase();

    if (lower.includes('skill') || lower.includes('tech') || lower.includes('stack')) {
      return "Rohit's tech stack includes Angular (v8-15), React, Next.js, Node.js, Spring Boot, MySQL, and PostgreSQL. He's highly skilled in building scalable frontends and managing complex state.";
    }

    if (lower.includes('experience') || lower.includes('work') || lower.includes('job') || lower.includes('company')) {
      return "Rohit is currently a Senior Software Developer at Iwin Labs (Nov 2025 - Present) leading a team of 5+ engineers building iGaming apps. Previously, he was at Centricity Wealth Tech (Apr 2024 - Oct 2025) building fintech platforms like One-Sure and One Digital, and ERP at Amstech Inc (Aug 2021 - Feb 2024).";
    }

    if (lower.includes('education') || lower.includes('degree') || lower.includes('college') || lower.includes('university')) {
      return "Rohit holds a Bachelor of Engineering in Information Technology from Swami Vivekananda College of Engineering, Indore (2016 - 2020).";
    }

    if (lower.includes('language') || lower.includes('speak')) {
      return "Rohit is fluent in both Hindi and English.";
    }

    if (lower.includes('project') || lower.includes('portfolio') || lower.includes('built')) {
      return "Rohit has built numerous major projects including: 'Learning 1080' (EdTech), 'OfferSA' (Multilingual Insurance app), 'CMS IIM Indore', 'HRMS', 'One Digital' (Fintech app with STT/TTS chatbot), 'One Sure' (Insurance platform), and iGaming platforms like 'Lady Lucka' and 'Rush of Gold'.";
    }

    if (lower.includes('contact') || lower.includes('email') || lower.includes('phone') || lower.includes('hire')) {
      return "You can reach Rohit via email at pancholirohit21@gmail.com, or call him at +91 7987228496. He's based in Indore, Madhya Pradesh.";
    }

    if (lower.includes('hi') || lower.includes('hello') || lower.includes('hey')) {
      return "Hello there! How can I help you learn more about Rohit today?";
    }

    if (lower.includes('who are you') || lower.includes('what are you')) {
      return "I am a virtual AI assistant built by Rohit to answer questions about his professional background. I'm running right here in your browser!";
    }

    return "That's an interesting question! While I don't have a specific answer for that, I can definitely tell you about Rohit's skills, experience, or projects. What would you like to know?";
  };

  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim()) return;

    const userText = inputValue.trim();
    const newUserMsg: Message = {
      id: Date.now().toString(),
      sender: 'user',
      text: userText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, newUserMsg]);
    setInputValue('');
    setIsTyping(true);

    // Simulate network delay and AI processing
    setTimeout(() => {
      const responseText = analyzeMessage(userText);
      const newAiMsg: Message = {
        id: (Date.now() + 1).toString(),
        sender: 'ai',
        text: responseText,
        timestamp: new Date()
      };
      setMessages(prev => [...prev, newAiMsg]);
      setIsTyping(false);
    }, 1200 + Math.random() * 800); // 1.2s to 2s random delay
  };

  return (
    <div className={`flex flex-col h-full w-full font-sans transition-colors ${isLight ? 'bg-slate-50 text-slate-900' : 'bg-slate-950 text-slate-100'}`}>

      {/* Header */}
      <div className={`flex items-center px-6 py-4 border-b ${isLight ? 'border-slate-200 bg-white/50' : 'border-white/10 bg-black/20'} backdrop-blur-md sticky top-0 z-10`}>
        <div className={`p-2 rounded-lg bg-gradient-to-br ${accentColor} mr-4 shadow-md`}>
          <Bot className="w-5 h-5 text-white" />
        </div>
        <div>
          <h2 className="text-xl font-bold tracking-tight">Virtual Rohit</h2>
          <p className={`text-xs flex items-center ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>
            <span className="w-2 h-2 rounded-full bg-emerald-500 mr-1.5 animate-pulse"></span>
            Online • This is a static chat bot
          </p>
        </div>
      </div>

      {/* Chat History */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6">
        {messages.map((msg) => {
          const isAi = msg.sender === 'ai';
          return (
            <div key={msg.id} className={`flex ${isAi ? 'justify-start' : 'justify-end'}`}>
              <div className={`flex max-w-[85%] ${isAi ? 'flex-row' : 'flex-row-reverse'}`}>

                {/* Avatar */}
                <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${isAi ? 'mr-3' : 'ml-3'} ${isAi ? `bg-gradient-to-br ${accentColor} text-white` : (isLight ? 'bg-slate-200 text-slate-500' : 'bg-slate-800 text-slate-400')}`}>
                  {isAi ? <Bot className="w-4 h-4" /> : <User className="w-4 h-4" />}
                </div>

                {/* Message Bubble */}
                <div>
                  <div className={`px-4 py-3 rounded-2xl ${isAi
                    ? (isLight ? 'bg-white border border-slate-200 shadow-sm text-slate-700' : 'bg-white/10 border border-white/5 text-slate-200')
                    : `bg-gradient-to-br ${accentColor} text-white shadow-md`
                    }`}>
                    <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</p>
                  </div>
                  <p className={`text-[10px] mt-1.5 px-2 ${isAi ? 'text-left' : 'text-right'} ${isLight ? 'text-slate-400' : 'text-slate-500'}`}>
                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </p>
                </div>

              </div>
            </div>
          );
        })}

        {/* Typing Indicator */}
        {isTyping && (
          <div className="flex justify-start">
            <div className="flex max-w-[80%] flex-row">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 mr-3 bg-gradient-to-br ${accentColor} text-white`}>
                <Bot className="w-4 h-4" />
              </div>
              <div className={`px-4 py-4 rounded-2xl flex items-center gap-1.5 ${isLight ? 'bg-white border border-slate-200 shadow-sm' : 'bg-white/10 border border-white/5'}`}>
                <span className="w-1.5 h-1.5 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '0ms' }}></span>
                <span className="w-1.5 h-1.5 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '150ms' }}></span>
                <span className="w-1.5 h-1.5 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: '300ms' }}></span>
              </div>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className={`p-4 border-t ${isLight ? 'bg-white border-slate-200' : 'bg-slate-900 border-white/10'}`}>
        <form onSubmit={handleSendMessage} className="relative flex items-center">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            placeholder="Ask about my skills, experience, or projects..."
            className={`w-full pl-4 pr-24 py-3 rounded-xl outline-none text-sm transition-all ${isLight ? 'bg-slate-100 placeholder:text-slate-400 focus:bg-white focus:ring-2 focus:ring-slate-200' : 'bg-slate-800 placeholder:text-slate-500 focus:bg-slate-800 focus:ring-2 focus:ring-slate-700'}`}
          />
          <div className="absolute right-2 flex items-center gap-1">
            <button
              type="button"
              onClick={startListening}
              className={`p-2 rounded-lg transition-all ${isListening ? 'bg-red-500/20 text-red-500 animate-pulse' : (isLight ? 'text-slate-400 hover:text-slate-600 hover:bg-black/5' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5')}`}
              title="Use microphone"
            >
              <Mic className="w-4 h-4" />
            </button>
            <button 
              type="submit"
              disabled={!inputValue.trim() || isTyping}
              className={`p-2 rounded-lg transition-colors ${!inputValue.trim() || isTyping ? 'opacity-30 cursor-not-allowed text-slate-500' : (isLight ? 'text-indigo-600 hover:bg-indigo-50' : 'text-indigo-400 hover:bg-indigo-500/20')}`}
            >
              <Send className="w-4 h-4" />
            </button>
          </div>
        </form>
      </div>

    </div>
  );
}

