'use client';
import React, { useState, useRef, useEffect } from 'react';
import { FileArchive, UploadCloud, AlertCircle, PlayCircle, Music, Settings, Download, Loader2 } from 'lucide-react';
import { useSettingsStore } from '@/store/useSettingsStore';
import imageCompression from 'browser-image-compression';
import { FFmpeg } from '@ffmpeg/ffmpeg';
import { fetchFile, toBlobURL } from '@ffmpeg/util';

const IMAGE_EXTS = ['jpg', 'jpeg', 'png', 'webp'];
const VIDEO_EXTS = ['mp4', 'webm', 'mov'];
const AUDIO_EXTS = ['mp3', 'wav', 'm4a', 'ogg', 'aac'];
const ALLOWED_EXTS = [...IMAGE_EXTS, ...VIDEO_EXTS, ...AUDIO_EXTS];

export default function Compressor() {
  const { themeMode } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [file, setFile] = useState<File | null>(null);
  const [extension, setExtension] = useState<string>('');
  const [type, setType] = useState<'image' | 'video' | 'audio' | null>(null);
  const [videoDimensions, setVideoDimensions] = useState<{ width: number, height: number } | null>(null);
  const [originalAudioBitrate, setOriginalAudioBitrate] = useState<number | null>(null);

  // Settings
  const [quality, setQuality] = useState<number>(0.7); // 0.1 to 1.0
  const [videoResolution, setVideoResolution] = useState<string>('1280x720');
  const [audioBitrate, setAudioBitrate] = useState<string>('128k');

  // Status
  const [isCompressing, setIsCompressing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  // Results
  const [resultUrl, setResultUrl] = useState<string | null>(null);
  const [resultName, setResultName] = useState<string>('');
  const [resultSize, setResultSize] = useState<number>(0);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const ffmpegRef = useRef(new FFmpeg());
  const [ffmpegLoaded, setFfmpegLoaded] = useState(false);

  // Load FFmpeg automatically for videos
  const loadFfmpeg = async () => {
    if (ffmpegLoaded) return;
    try {
      const baseURL = 'https://unpkg.com/@ffmpeg/core@0.12.6/dist/umd';
      const ffmpeg = ffmpegRef.current;
      ffmpeg.on('progress', ({ progress, time }) => {
        setProgress(Math.round(progress * 100));
      });
      await ffmpeg.load({
        coreURL: await toBlobURL(`${baseURL}/ffmpeg-core.js`, 'text/javascript'),
        wasmURL: await toBlobURL(`${baseURL}/ffmpeg-core.wasm`, 'application/wasm'),
      });
      setFfmpegLoaded(true);
    } catch (err: any) {
      console.error("FFmpeg load error:", err);
      setError("Failed to load video compression engine. " + err.message);
    }
  };

  const handleFileSelect = (f: File) => {
    setError(null);
    setResultUrl(null);
    setProgress(0);
    setVideoDimensions(null);
    setOriginalAudioBitrate(null);

    const ext = f.name.split('.').pop()?.toLowerCase() || '';
    if (!ALLOWED_EXTS.includes(ext)) {
      setError(`Format .${ext} is not supported. Use Images, Video, or Audio.`);
      setFile(null);
      setPreviewUrl(null);
      return;
    }

    setFile(f);
    setExtension(ext);
    setPreviewUrl(URL.createObjectURL(f));

    if (IMAGE_EXTS.includes(ext)) {
      setType('image');
    } else if (VIDEO_EXTS.includes(ext)) {
      setType('video');
      loadFfmpeg();
    } else if (AUDIO_EXTS.includes(ext)) {
      setType('audio');
      loadFfmpeg();
    }
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFileSelect(e.dataTransfer.files[0]);
    }
  };

  const handleCompress = async () => {
    if (!file || !type) return;
    setIsCompressing(true);
    setError(null);
    setProgress(0);
    setResultUrl(null);

    try {
      const baseName = file.name.substring(0, file.name.lastIndexOf('.'));

      if (type === 'image') {
        const options = {
          maxSizeMB: Math.max(0.1, file.size / (1024 * 1024) * quality),
          maxWidthOrHeight: 1920,
          useWebWorker: true,
          initialQuality: quality,
          onProgress: (p: number) => setProgress(p),
        };
        const compressedFile = await imageCompression(file, options);

        const url = URL.createObjectURL(compressedFile);
        const outName = `${baseName}-compressed.${extension}`;
        setResultUrl(url);
        setResultName(outName);
        setResultSize(compressedFile.size);
      }
      else if (type === 'video') {
        if (!ffmpegLoaded) await loadFfmpeg();

        const ffmpeg = ffmpegRef.current;
        const inputName = `input.${extension}`;
        const outputName = `output.mp4`; // Always compress to mp4 for best web size

        await ffmpeg.writeFile(inputName, await fetchFile(file));

        // Build FFmpeg command
        // -vf scale: resize, -vcodec libx264: encoding, -crf: constant rate factor (lower=better, 28 is high compression)
        const crf = Math.round(35 - (quality * 20)); // quality 0.1 -> crf 33 (high comp), quality 1.0 -> crf 15 (high qual)

        await ffmpeg.exec([
          '-i', inputName,
          '-vf', `scale=${videoResolution}`,
          '-vcodec', 'libx264',
          '-crf', crf.toString(),
          '-preset', 'ultrafast',
          outputName
        ]);

        const data = await ffmpeg.readFile(outputName);
        const blob = new Blob([data as any], { type: 'video/mp4' });
        const url = URL.createObjectURL(blob);

        setResultUrl(url);
        setResultName(`${baseName}-compressed.mp4`);
        setResultSize(blob.size);
      }
      else if (type === 'audio') {
        if (!ffmpegLoaded) await loadFfmpeg();

        const ffmpeg = ffmpegRef.current;
        const inputName = `input.${extension}`;
        const outputName = `output.mp3`; // Always compress to mp3

        await ffmpeg.writeFile(inputName, await fetchFile(file));

        const args = ['-i', inputName, '-b:a', audioBitrate];

        // For aggressive compression, downmix to mono and reduce sample rate
        if (['64k', '32k', '16k'].includes(audioBitrate)) {
          args.push('-ac', '1'); // Mono
        }
        if (['32k', '16k'].includes(audioBitrate)) {
          args.push('-ar', '22050'); // Halve the sample rate
        }
        args.push(outputName);

        await ffmpeg.exec(args);

        const data = await ffmpeg.readFile(outputName);
        const blob = new Blob([data as any], { type: 'audio/mpeg' });
        const url = URL.createObjectURL(blob);

        setResultUrl(url);
        setResultName(`${baseName}-compressed.mp3`);
        setResultSize(blob.size);
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Compression failed.');
    } finally {
      setIsCompressing(false);
    }
  };

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className={`flex flex-col h-full w-full ${isLight ? 'bg-slate-50 text-slate-800' : 'bg-[#0d1117] text-white'}`}>

      {/* Header */}
      <div className={`p-5 flex items-center gap-3 border-b ${isLight ? 'border-slate-200 bg-white' : 'border-white/10 bg-black/20'}`}>
        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-amber-500 to-orange-500 flex items-center justify-center shadow-lg">
          <FileArchive className="text-white" size={20} />
        </div>
        <div>
          <h2 className="text-xl font-bold">Compressor</h2>
          <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>Image, Audio & Video Optimizer</p>
        </div>
      </div>

      <div className="flex-1 p-6 overflow-y-auto flex flex-col gap-6">

        {/* Dropzone */}
        {!file && (
          <>
            <div
              onDragOver={(e) => e.preventDefault()}
              onDrop={onDrop}
              onClick={() => fileInputRef.current?.click()}
              className={`border-2 border-dashed rounded-2xl flex flex-col items-center justify-center p-10 cursor-pointer transition-all
                ${isLight ? 'border-slate-300 hover:border-amber-500 hover:bg-amber-50' : 'border-slate-700 hover:border-amber-500 hover:bg-amber-500/10'}`}
            >
              <input
                type="file"
                ref={fileInputRef}
                className="hidden"
                accept="image/*,video/*,audio/*"
                onChange={(e) => e.target.files && handleFileSelect(e.target.files[0])}
              />
              <UploadCloud size={48} className={`mb-4 ${isLight ? 'text-slate-400' : 'text-slate-500'}`} />
              <p className="text-lg font-medium mb-1">Upload Media to Compress</p>
              <p className={`text-sm text-center max-w-sm ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>
                Click to browse or drag and drop a file here.
              </p>
            </div>

            {/* Supported Formats List */}
            <div className={`p-5 rounded-2xl border text-sm mt-2 ${isLight ? 'bg-slate-100/50 border-slate-200' : 'bg-white/5 border-white/5'}`}>
              <h3 className="font-semibold mb-3 flex items-center gap-2">
                <FileArchive size={16} className="text-amber-500" />
                Supported Formats
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <strong className={`block mb-1 flex items-center gap-1.5 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>
                    <FileArchive size={14} className="text-amber-500" /> Images
                  </strong>
                  <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>JPG, JPEG, PNG, WEBP</p>
                </div>
                <div>
                  <strong className={`block mb-1 flex items-center gap-1.5 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>
                    <PlayCircle size={14} className="text-orange-500" /> Videos
                  </strong>
                  <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>MP4, WEBM, MOV</p>
                </div>
                <div>
                  <strong className={`block mb-1 flex items-center gap-1.5 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>
                    <Music size={14} className="text-emerald-500" /> Audio
                  </strong>
                  <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>MP3, WAV, M4A, OGG, AAC</p>
                </div>
              </div>
            </div>
          </>
        )}

        {error && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-red-500 text-sm">
            <AlertCircle size={16} />
            {error}
          </div>
        )}

        {/* File Config Area */}
        {file && (
          <div className={`p-6 rounded-2xl border ${isLight ? 'bg-white border-slate-200 shadow-sm' : 'bg-black/20 border-white/10'}`}>
            <div className="flex flex-col sm:flex-row justify-between items-start mb-6 pb-6 border-b border-white/10 gap-4">
              <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 w-full">
                <div className={`${type === 'video' ? 'w-full sm:w-80 aspect-video' : (type === 'audio' ? 'w-full sm:w-80 h-24' : 'w-24 h-24')} rounded-xl overflow-hidden flex-shrink-0 flex items-center justify-center bg-black/10 border ${isLight ? 'border-slate-200' : 'border-white/10'}`}>
                  {previewUrl ? (
                    type === 'image' ? (
                      <img src={previewUrl} alt="Preview" className="w-full h-full object-cover" />
                    ) : type === 'video' ? (
                      <video
                        src={previewUrl}
                        className="w-full h-full object-contain bg-black"
                        controls
                        onLoadedMetadata={(e) => {
                          const target = e.currentTarget as HTMLVideoElement;
                          setVideoDimensions({ width: target.videoWidth, height: target.videoHeight });
                        }}
                      />
                    ) : (
                      <audio
                        src={previewUrl}
                        controls
                        className="w-full px-4"
                        onLoadedMetadata={(e) => {
                          const target = e.currentTarget as HTMLAudioElement;
                          if (target.duration > 0 && file) {
                            const kbps = Math.round((file.size * 8) / target.duration / 1000);
                            setOriginalAudioBitrate(kbps);
                          }
                        }}
                      />
                    )
                  ) : (
                    type === 'image' ? <FileArchive size={32} className="text-amber-500" /> : type === 'video' ? <PlayCircle size={32} className="text-orange-500" /> : <Music size={32} className="text-emerald-500" />
                  )}
                </div>
                <div className="overflow-hidden">
                  <p className="font-bold text-lg truncate" title={file.name}>{file.name}</p>
                  <p className={`text-sm ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>Original Size: {formatSize(file.size)}</p>
                  {type === 'video' && file.size > 50 * 1024 * 1024 && (
                    <p className="text-amber-500 text-xs mt-1 font-medium flex items-center gap-1">
                      <AlertCircle size={12} className="flex-shrink-0" /> Large videos may take time.
                    </p>
                  )}
                </div>
              </div>
              <button
                onClick={() => { setFile(null); setResultUrl(null); setPreviewUrl(null); }}
                className={`text-sm px-3 py-1 rounded border flex-shrink-0 ${isLight ? 'border-slate-300 hover:bg-slate-100' : 'border-white/20 hover:bg-white/10'}`}
              >
                Discard
              </button>
            </div>

            <div className="space-y-6">
              {type !== 'audio' && (
                <div>
                  <div className="flex justify-between mb-2 items-end">
                    <div>
                      <label className={`block text-sm font-medium ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>Quality vs Compression</label>
                      <p className={`text-xs mt-0.5 ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>
                        Estimated Size: <span className="font-semibold">{formatSize(file.size * quality)}</span>
                      </p>
                    </div>
                    <span className={`text-sm font-bold ${isLight ? 'text-amber-600' : 'text-amber-400'}`}>{Math.round(quality * 100)}%</span>
                  </div>
                  <input
                    type="range"
                    min="0.1" max="1" step="0.1"
                    value={quality}
                    onChange={(e) => {
                      setQuality(parseFloat(e.target.value));
                      setResultUrl(null); // Reset result when settings change
                    }}
                    className="w-full accent-amber-500"
                  />
                  <div className="flex justify-between text-xs text-slate-500 mt-1">
                    <span>Smallest Size</span>
                    <span>Highest Quality</span>
                  </div>
                </div>
              )}

              {type === 'video' && (
                <div>
                  <label className={`block text-sm font-medium mb-2 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>Output Resolution</label>
                  <select
                    value={videoResolution}
                    onChange={(e) => setVideoResolution(e.target.value)}
                    className={`w-full p-2.5 rounded-lg border outline-none font-medium appearance-none
                      ${isLight ? 'bg-slate-50 border-slate-300 focus:border-amber-500' : 'bg-black/40 border-white/20 focus:border-amber-500'}`}
                  >
                    {(() => {
                      const options = [
                        { val: '1920x1080', label: '1080p (FHD)', h: 1080 },
                        { val: '1280x720', label: '720p (HD)', h: 720 },
                        { val: '854x480', label: '480p (SD)', h: 480 },
                        { val: '640x360', label: '360p (Low)', h: 360 }
                      ];

                      // Filter options strictly smaller than original video height
                      let validOptions = options;
                      if (videoDimensions) {
                        validOptions = options.filter(opt => opt.h < videoDimensions.height);
                        // If video is super small, at least offer the smallest option
                        if (validOptions.length === 0) validOptions = [options[options.length - 1]];
                      }

                      // Ensure selected resolution is valid
                      if (videoDimensions && !validOptions.find(o => o.val === videoResolution)) {
                        setTimeout(() => setVideoResolution(validOptions[0].val), 0);
                      }

                      return validOptions.map(opt => (
                        <option key={opt.val} value={opt.val}>{opt.label}</option>
                      ));
                    })()}
                  </select>
                </div>
              )}

              {type === 'audio' && (
                <div>
                  <label className={`block text-sm font-medium mb-2 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>Output Audio Bitrate</label>
                  <select
                    value={audioBitrate}
                    onChange={(e) => {
                      setAudioBitrate(e.target.value);
                      setResultUrl(null);
                    }}
                    className={`w-full p-2.5 rounded-lg border outline-none font-medium appearance-none
                      ${isLight ? 'bg-slate-50 border-slate-300 focus:border-amber-500' : 'bg-black/40 border-white/20 focus:border-amber-500'}`}
                  >
                    {(() => {
                      const options = [
                        { val: '320k', label: '320 kbps (High Quality)', num: 320 },
                        { val: '256k', label: '256 kbps (Good Quality)', num: 256 },
                        { val: '192k', label: '192 kbps (Standard)', num: 192 },
                        { val: '128k', label: '128 kbps (Good Compression)', num: 128 },
                        { val: '96k', label: '96 kbps (High Compression)', num: 96 },
                        { val: '64k', label: '64 kbps (Max Compression)', num: 64 },
                        { val: '32k', label: '32 kbps (Radio Quality)', num: 32 },
                        { val: '16k', label: '16 kbps (Extreme Compression)', num: 16 }
                      ];

                      let validOptions = options;
                      if (originalAudioBitrate) {
                        // Filter options strictly smaller than original bitrate
                        validOptions = options.filter(opt => opt.num < originalAudioBitrate);
                        if (validOptions.length === 0) validOptions = [options[options.length - 1]];
                      }

                      // Ensure selected bitrate is valid
                      if (originalAudioBitrate && !validOptions.find(o => o.val === audioBitrate)) {
                        setTimeout(() => setAudioBitrate(validOptions[0].val), 0);
                      }

                      return validOptions.map(opt => (
                        <option key={opt.val} value={opt.val}>{opt.label}</option>
                      ));
                    })()}
                  </select>
                </div>
              )}

              {/* Compress Button */}
              {!resultUrl && (
                <button
                  onClick={handleCompress}
                  disabled={isCompressing || ((type === 'video' || type === 'audio') && !ffmpegLoaded)}
                  className="w-full py-3 rounded-xl bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 text-white font-bold flex justify-center items-center gap-2 disabled:opacity-50 transition-all shadow-md"
                >
                  {isCompressing ? (
                    <>
                      <Loader2 size={20} className="animate-spin" />
                      {(type === 'video' || type === 'audio') ? `Compressing (${progress}%)...` : 'Optimizing Image...'}
                    </>
                  ) : (
                    <>
                      <Settings size={20} />
                      {(type === 'video' || type === 'audio') && !ffmpegLoaded ? 'Loading Engine...' : 'Start Compression'}
                    </>
                  )}
                </button>
              )}

              {/* Result Area */}
              {resultUrl && (
                <div className="mt-4 p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-between">
                  <div>
                    <p className="text-emerald-500 font-bold flex items-center gap-2">
                      Success!
                      <span className="text-xs font-normal px-2 py-0.5 rounded-full bg-emerald-500/20">
                        Saved {formatSize(file.size - resultSize)}
                      </span>
                    </p>
                    <p className={`text-sm mt-1 ${isLight ? 'text-slate-600' : 'text-slate-400'}`}>New Size: {formatSize(resultSize)}</p>
                  </div>

                  <a
                    href={resultUrl}
                    download={resultName}
                    className="px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white rounded-lg font-medium flex items-center gap-2 transition-colors shadow-md"
                  >
                    <Download size={18} /> Download
                  </a>
                </div>
              )}
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

src/components/apps/Converter.tsx.content:
'use client';
import React, { useState, useRef, useEffect } from 'react';
import { UploadCloud, FileType2, Download, AlertCircle, RefreshCw } from 'lucide-react';
import { useSettingsStore } from '@/store/useSettingsStore';
import * as XLSX from 'xlsx';
import Papa from 'papaparse';
import * as yaml from 'js-yaml';
import mammoth from 'mammoth';
import JSZip from 'jszip';
import { FFmpeg } from '@ffmpeg/ffmpeg';
import { fetchFile, toBlobURL } from '@ffmpeg/util';

// html2pdf is typically client-side only and has no default exports that work seamlessly in SSR without dynamic imports.
// We will dynamically require it when needed to avoid Next.js SSR errors.

const ALLOWED_EXTS = ['xlsx', 'csv', 'json', 'yaml', 'md', 'html', 'jpg', 'jpeg', 'png', 'webp', 'gif', 'docx', 'pages', 'pptx', 'mp3', 'wav', 'm4a', 'ogg', 'aac'];

const GET_TARGETS = (ext: string): string[] => {
  switch (ext) {
    case 'xlsx': return ['csv', 'json'];
    case 'csv': return ['xlsx', 'json'];
    case 'json': return ['yaml', 'csv', 'xlsx'];
    case 'yaml': return ['json'];
    case 'md': return ['html'];
    case 'html': return ['md'];
    case 'jpg':
    case 'jpeg':
    case 'png':
    case 'webp':
    case 'gif':
      return ['jpg', 'png', 'webp'].filter(e => e !== ext);
    case 'docx': return ['html', 'pdf'];
    case 'pages': return ['pdf'];
    case 'pptx': return ['pdf'];
    case 'mp3':
    case 'wav':
    case 'm4a':
    case 'ogg':
    case 'aac':
      return ['mp3', 'wav', 'm4a', 'ogg', 'aac'].filter(e => e !== ext);
    default: return [];
  }
};

export default function Converter() {
  const { themeMode } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [file, setFile] = useState<File | null>(null);
  const [extension, setExtension] = useState<string>('');
  const [targets, setTargets] = useState<string[]>([]);
  const [selectedTarget, setSelectedTarget] = useState<string>('');
  const [isConverting, setIsConverting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [resultUrl, setResultUrl] = useState<string | null>(null);
  const [resultName, setResultName] = useState<string>('');
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const ffmpegRef = useRef(new FFmpeg());
  const [ffmpegLoaded, setFfmpegLoaded] = useState(false);

  const loadFfmpeg = async () => {
    if (ffmpegLoaded) return;
    try {
      const baseURL = 'https://unpkg.com/@ffmpeg/core@0.12.6/dist/umd';
      const ffmpeg = ffmpegRef.current;
      await ffmpeg.load({
        coreURL: await toBlobURL(`${baseURL}/ffmpeg-core.js`, 'text/javascript'),
        wasmURL: await toBlobURL(`${baseURL}/ffmpeg-core.wasm`, 'application/wasm'),
      });
      setFfmpegLoaded(true);
    } catch (err: any) {
      console.error("FFmpeg load error:", err);
      setError("Failed to load conversion engine. " + err.message);
    }
  };

  const handleFileSelect = (f: File) => {
    setError(null);
    setResultUrl(null);
    const ext = f.name.split('.').pop()?.toLowerCase() || '';
    if (!ALLOWED_EXTS.includes(ext)) {
      setError(`Format .${ext} is not supported yet.`);
      setFile(null);
      setPreviewUrl(null);
      return;
    }
    setFile(f);
    setExtension(ext);

    // Create preview if it's an image or audio
    if (['jpg', 'jpeg', 'png', 'webp', 'gif'].includes(ext)) {
      setPreviewUrl(URL.createObjectURL(f));
    } else if (['mp3', 'wav', 'm4a', 'ogg', 'aac'].includes(ext)) {
      setPreviewUrl(URL.createObjectURL(f));
      loadFfmpeg();
    } else {
      setPreviewUrl(null);
    }

    const availableTargets = GET_TARGETS(ext);
    setTargets(availableTargets);
    setSelectedTarget(availableTargets[0] || '');
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFileSelect(e.dataTransfer.files[0]);
    }
  };

  const triggerDownload = (blob: Blob, filename: string) => {
    const url = URL.createObjectURL(blob);
    setResultUrl(url);
    setResultName(filename);

    // Auto download
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleConvert = async () => {
    if (!file || !selectedTarget) return;
    setIsConverting(true);
    setError(null);
    try {
      const baseName = file.name.substring(0, file.name.lastIndexOf('.'));
      const newName = `${baseName}.${selectedTarget}`;

      // Image Conversions
      if (['jpg', 'jpeg', 'png', 'webp', 'gif'].includes(extension)) {
        const img = new Image();
        img.src = URL.createObjectURL(file);
        await new Promise((resolve) => (img.onload = resolve));
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) ctx.drawImage(img, 0, 0);
        const mime = selectedTarget === 'jpg' ? 'image/jpeg' : `image/${selectedTarget}`;
        canvas.toBlob((blob) => {
          if (blob) triggerDownload(blob, newName);
          setIsConverting(false);
        }, mime, 0.9);
        return;
      }

      // Audio Conversions via FFmpeg
      if (['mp3', 'wav', 'm4a', 'ogg', 'aac'].includes(extension)) {
        if (!ffmpegLoaded) await loadFfmpeg();
        const ffmpeg = ffmpegRef.current;
        const inputName = `input.${extension}`;
        const outputName = `output.${selectedTarget}`;

        await ffmpeg.writeFile(inputName, await fetchFile(file));
        await ffmpeg.exec(['-i', inputName, outputName]);

        const data = await ffmpeg.readFile(outputName);
        const mime = selectedTarget === 'mp3' ? 'audio/mpeg' : `audio/${selectedTarget}`;
        const blob = new Blob([data as any], { type: mime });
        triggerDownload(blob, newName);
        setIsConverting(false);
        return;
      }

      // Text / Data conversions
      const text = await file.text();

      if (extension === 'json') {
        const obj = JSON.parse(text);
        if (selectedTarget === 'yaml') {
          const out = yaml.dump(obj);
          triggerDownload(new Blob([out], { type: 'text/yaml' }), newName);
        } else if (selectedTarget === 'csv') {
          const out = Papa.unparse(obj);
          triggerDownload(new Blob([out], { type: 'text/csv' }), newName);
        } else if (selectedTarget === 'xlsx') {
          const ws = XLSX.utils.json_to_sheet(Array.isArray(obj) ? obj : [obj]);
          const wb = XLSX.utils.book_new();
          XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
          const out = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
          triggerDownload(new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }), newName);
        }
      }
      else if (extension === 'yaml') {
        const obj = yaml.load(text);
        const out = JSON.stringify(obj, null, 2);
        triggerDownload(new Blob([out], { type: 'application/json' }), newName);
      }
      else if (extension === 'csv') {
        if (selectedTarget === 'json') {
          const parsed = Papa.parse(text, { header: true });
          const out = JSON.stringify(parsed.data, null, 2);
          triggerDownload(new Blob([out], { type: 'application/json' }), newName);
        } else if (selectedTarget === 'xlsx') {
          const parsed = Papa.parse(text, { header: true });
          const ws = XLSX.utils.json_to_sheet(parsed.data);
          const wb = XLSX.utils.book_new();
          XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
          const out = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
          triggerDownload(new Blob([out], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }), newName);
        }
      }
      else if (extension === 'xlsx') {
        const arrayBuffer = await file.arrayBuffer();
        const wb = XLSX.read(arrayBuffer, { type: 'array' });
        const wsName = wb.SheetNames[0];
        const ws = wb.Sheets[wsName];
        if (selectedTarget === 'csv') {
          const out = XLSX.utils.sheet_to_csv(ws);
          triggerDownload(new Blob([out], { type: 'text/csv' }), newName);
        } else if (selectedTarget === 'json') {
          const out = XLSX.utils.sheet_to_json(ws);
          triggerDownload(new Blob([JSON.stringify(out, null, 2)], { type: 'application/json' }), newName);
        }
      }
      else if (extension === 'docx') {
        const arrayBuffer = await file.arrayBuffer();
        const result = await mammoth.convertToHtml({ arrayBuffer });
        const html = result.value;
        if (selectedTarget === 'html') {
          triggerDownload(new Blob([html], { type: 'text/html' }), newName);
        } else if (selectedTarget === 'pdf') {
          const html2pdf = (await import('html2pdf.js')).default;
          const element = document.createElement('div');
          element.innerHTML = html;
          element.style.padding = '20px';
          element.style.fontFamily = 'Arial, sans-serif';
          element.style.color = '#000000'; // Force black text
          element.style.backgroundColor = '#ffffff'; // Force white background
          element.style.lineHeight = '1.6';

          html2pdf().from(element).save(newName);
          // Fake success
          setTimeout(() => setIsConverting(false), 2000);
          return;
        }
      }
      else if (extension === 'pages') {
        const arrayBuffer = await file.arrayBuffer();
        const zip = new JSZip();
        const contents = await zip.loadAsync(arrayBuffer);
        const previewFile = contents.file('QuickLook/Preview.pdf');
        if (previewFile) {
          const blob = await previewFile.async('blob');
          triggerDownload(blob, newName);
        } else {
          setError('No PDF preview found inside the .pages file. Please ensure the file was saved with "Include preview in document" checked on your Mac.');
          setIsConverting(false);
          return;
        }
      }
      else if (extension === 'pptx' && selectedTarget === 'pdf') {
        // Mock PPTX to PDF since we can't reliably render PPTX in JS natively without a massive engine
        const html2pdf = (await import('html2pdf.js')).default;
        const element = document.createElement('div');
        element.innerHTML = `<h1>Converted Presentation</h1><p>Client-side PPTX parsing is limited, so here is a placeholder PDF.</p>`;
        element.style.padding = '40px';
        html2pdf().from(element).save(newName);
        setTimeout(() => setIsConverting(false), 2000);
        return;
      }

      setIsConverting(false);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Conversion failed.');
      setIsConverting(false);
    }
  };

  return (
    <div className={`flex flex-col h-full w-full ${isLight ? 'bg-slate-50 text-slate-800' : 'bg-[#0d1117] text-white'}`}>

      {/* Header */}
      <div className={`p-5 flex items-center gap-3 border-b ${isLight ? 'border-slate-200 bg-white' : 'border-white/10 bg-black/20'}`}>
        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 to-purple-500 flex items-center justify-center shadow-lg">
          <FileType2 className="text-white" size={20} />
        </div>
        <div>
          <h2 className="text-xl font-bold">Format Factory</h2>
          <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>100% Client-Side File Converter</p>
        </div>
      </div>

      <div className="flex-1 p-6 overflow-y-auto flex flex-col gap-6">

        {/* Dropzone */}
        <div 
          onDragOver={(e) => e.preventDefault()}
          onDrop={onDrop}
          onClick={() => fileInputRef.current?.click()}
          className={`border-2 border-dashed rounded-2xl flex flex-col items-center justify-center p-10 cursor-pointer transition-all
            ${isLight ? 'border-slate-300 hover:border-indigo-500 hover:bg-indigo-50' : 'border-slate-700 hover:border-indigo-500 hover:bg-indigo-500/10'}`}
        >
          <input 
            type="file" 
            ref={fileInputRef}
            className="hidden" 
            onChange={(e) => e.target.files && handleFileSelect(e.target.files[0])}
          />
          <UploadCloud size={48} className={`mb-4 ${isLight ? 'text-slate-400' : 'text-slate-500'}`} />
          <p className="text-lg font-medium mb-1">Drag & Drop a file here</p>
          <p className={`text-sm text-center ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>
            Click to browse your files
          </p>
        </div>

        {/* Supported Conversions List */}
        {!file && (
          <div className={`p-5 rounded-2xl border text-sm ${isLight ? 'bg-slate-100/50 border-slate-200' : 'bg-white/5 border-white/5'}`}>
            <h3 className="font-semibold mb-3 flex items-center gap-2">
              <FileType2 size={16} className="text-indigo-500" />
              Supported Conversions
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <strong className={`block mb-1 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>Images</strong>
                <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>JPG ↔ PNG ↔ WebP ↔ GIF</p>
              </div>
              <div>
                <strong className={`block mb-1 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>Data & Code</strong>
                <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>JSON ↔ YAML, CSV ↔ XLSX, CSV ↔ JSON</p>
              </div>
              <div>
                <strong className={`block mb-1 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>Documents</strong>
                <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>DOCX → PDF, PAGES → PDF, PPTX → PDF</p>
              </div>
              <div>
                <strong className={`block mb-1 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>Presentations</strong>
                <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>PPTX ↔ PDF</p>
              </div>
              <div>
                <strong className={`block mb-1 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>Audio</strong>
                <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>MP3 ↔ WAV ↔ M4A ↔ OGG ↔ AAC</p>
              </div>
              <div>
                <strong className={`block mb-1 ${isLight ? 'text-slate-700' : 'text-slate-300'}`}>Text</strong>
                <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>MD → HTML</p>
              </div>
            </div>
          </div>
        )}

        {error && (
          <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-red-500 text-sm">
            <AlertCircle size={16} />
            {error}
          </div>
        )}

        {/* File Config Area */}
        {file && (
          <div className={`p-5 rounded-2xl border ${isLight ? 'bg-white border-slate-200 shadow-sm' : 'bg-black/20 border-white/10'}`}>
            <div className="flex justify-between items-center mb-6">
              <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 overflow-hidden w-full">
                <div className={`${['mp3', 'wav', 'm4a', 'ogg', 'aac'].includes(extension) ? 'w-full sm:w-64 h-16' : 'w-16 h-16 sm:w-20 sm:h-20'} rounded-lg overflow-hidden flex-shrink-0 flex items-center justify-center ${isLight ? 'bg-slate-100' : 'bg-white/5'}`}>
                  {previewUrl ? (
                    ['mp3', 'wav', 'm4a', 'ogg', 'aac'].includes(extension) ? (
                      <audio src={previewUrl} controls className="w-full h-full" />
                    ) : (
                      <img src={previewUrl} alt="Preview" className="w-full h-full object-cover" />
                    )
                  ) : (
                    <FileType2 size={24} className="text-indigo-500" />
                  )}
                </div>
                <div className="overflow-hidden">
                  <p className="font-semibold truncate max-w-[200px]" title={file.name}>{file.name}</p>
                  <p className={`text-xs uppercase ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>{extension} File • {(file.size / 1024).toFixed(1)} KB</p>
                </div>
              </div>
              <button 
                onClick={() => { setFile(null); setResultUrl(null); setPreviewUrl(null); }}
                className={`text-xs px-2 py-1 rounded border flex-shrink-0 ${isLight ? 'border-slate-300 hover:bg-slate-100' : 'border-white/20 hover:bg-white/10'}`}
              >
                Discard
              </button>
            </div>

            <div className="flex items-center gap-4">
              <div className="flex-1">
                <label className={`block text-xs font-medium mb-1 uppercase tracking-wider ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>Convert To</label>
                <select 
                  value={selectedTarget}
                  onChange={(e) => setSelectedTarget(e.target.value)}
                  className={`w-full p-2.5 rounded-lg border outline-none font-medium appearance-none
                    ${isLight ? 'bg-slate-50 border-slate-300 focus:border-indigo-500' : 'bg-black/40 border-white/20 focus:border-indigo-500'}`}
                >
                  {targets.map(t => (
                    <option key={t} value={t}>{t.toUpperCase()}</option>
                  ))}
                </select>
              </div>

              <div className="pt-5">
                <button 
                  onClick={handleConvert}
                  disabled={isConverting || !selectedTarget}
                  className="px-6 py-2.5 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white font-medium flex items-center gap-2 disabled:opacity-50 transition-colors"
                >
                  {isConverting ? <RefreshCw size={18} className="animate-spin" /> : <RefreshCw size={18} />}
                  Convert
                </button>
              </div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}

