import React, { useState, useEffect, useRef, memo } from 'react';
import YouTube, { YouTubeProps, YouTubePlayer } from 'react-youtube';
import { Play, Pause, SkipForward, SkipBack, Shuffle, ListVideo, Music } from 'lucide-react';
import { useSettingsStore } from '@/store/useSettingsStore';

// Playlist categories
const PLAYLISTS = [
  { id: 'PL4fGSI1pDJn6puJdseH2Rt9sMvt9E2M4i', name: 'Global Top 100', cover: 'https://images.unsplash.com/photo-1459749411175-04bf5292ceea?w=500&q=80' },
  { id: 'PL4fGSI1pDJn4pTWyM3t61lOyZ6_4jcNOw', name: 'India Top 100', cover: 'https://images.unsplash.com/photo-1524492412937-b28074a5d7da?w=500&q=80' },
  { id: 'PLeatb7hupNV_AWUl_7ttbsKeCQh8tF5N4', name: 'Truck Wala (90s)', cover: 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=500&q=80' }
];

// --- Extracted ProgressBar to prevent main component from re-rendering every 1s ---
const ProgressBar = memo(({ player, duration }: { player: YouTubePlayer | null, duration: number }) => {
  const [currentTime, setCurrentTime] = useState(0);

  useEffect(() => {
    if (!player) return;
    const interval = setInterval(() => {
      // Poll YouTube player for current time
      const time = player.getCurrentTime();
      if (typeof time === 'number') {
        setCurrentTime(time);
      }
    }, 1000);
    return () => clearInterval(interval);
  }, [player]);

  const handleSeek = (e: React.ChangeEvent<HTMLInputElement>) => {
    const time = Number(e.target.value);
    setCurrentTime(time);
    if (player) {
      player.seekTo(time, true);
    }
  };

  const formatTime = (seconds: number) => {
    if (!seconds || isNaN(seconds)) return '0:00';
    const m = Math.floor(seconds / 60);
    const s = Math.floor(seconds % 60);
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  return (
    <div className="w-full max-w-xs sm:max-w-md flex flex-col gap-2 mb-6 sm:mb-8 px-4">
      <input 
        type="range" 
        min="0" 
        max={duration || 100} 
        value={currentTime ?? 0} 
        onChange={handleSeek}
        className="w-full h-1.5 bg-slate-500/30 rounded-lg appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3 [&::-webkit-slider-thumb]:h-3 [&::-webkit-slider-thumb]:bg-indigo-500 [&::-webkit-slider-thumb]:rounded-full transition-all hover:[&::-webkit-slider-thumb]:scale-125"
      />
      <div className="flex justify-between text-xs opacity-60 font-medium">
        <span>{formatTime(currentTime)}</span>
        <span>{formatTime(duration)}</span>
      </div>
    </div>
  );
});
ProgressBar.displayName = 'ProgressBar';

const MusicPlayer: React.FC = () => {
  const [player, setPlayer] = useState<YouTubePlayer | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentPlaylist, setCurrentPlaylist] = useState(PLAYLISTS[0]);
  const [duration, setDuration] = useState(0);
  const [isShuffle, setIsShuffle] = useState(false);
  const [showPlaylists, setShowPlaylists] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'categories' | 'queue'>('categories');
  const [trackInfo, setTrackInfo] = useState({ title: 'Loading...', artist: 'Please wait', videoId: '' });
  const [playlistTracks, setPlaylistTracks] = useState<string[]>([]);
  const [currentTrackIndex, setCurrentTrackIndex] = useState(0);

  const { themeMode } = useSettingsStore();
  const isLight = themeMode === 'light';

  // YouTube player options - dynamically update based on current playlist
  const opts: YouTubeProps['opts'] = {
    height: '200',
    width: '200',
    playerVars: {
      autoplay: 1,
      listType: 'playlist',
      list: currentPlaylist.id,
    },
  };

  const onReady: YouTubeProps['onReady'] = (event) => {
    setPlayer(event.target);
    event.target.setShuffle(isShuffle);
  };

  const onStateChange: YouTubeProps['onStateChange'] = (event) => {
    // 1 is PLAYING, 2 is PAUSED, 0 is ENDED
    if (event.data === 1) {
      setIsPlaying(true);
      setDuration(event.target.getDuration());

      // Attempt to get video data
      const videoData = event.target.getVideoData();
      if (videoData) {
        setTrackInfo({
          title: videoData.title || 'Unknown Track',
          artist: videoData.author || 'Unknown Artist',
          videoId: videoData.video_id || ''
        });
      }

      // Update playlist queue info
      const tracks = event.target.getPlaylist() || [];
      if (tracks.length > 0 && tracks.length !== playlistTracks.length) {
        setPlaylistTracks(tracks);
      }
      setCurrentTrackIndex(event.target.getPlaylistIndex());
    } else {
      setIsPlaying(false);
    }
  };

  const onError: YouTubeProps['onError'] = (event) => {
    // 101 or 150 means the video cannot be embedded (copyright/permissions)
    if (event.data === 101 || event.data === 150) {
      console.warn('Video cannot be embedded, skipping to next...', event.data);
      event.target.nextVideo();
    } else {
      console.error('YouTube Player Error:', event.data);
      setTrackInfo({ title: 'Playback Error', artist: 'Please try another playlist', videoId: '' });
      setIsPlaying(false);
    }
  };

  const togglePlay = () => {
    if (!player) return;
    if (isPlaying) {
      player.pauseVideo();
    } else {
      player.playVideo();
    }
  };

  const nextTrack = () => {
    if (player) player.nextVideo();
  };

  const prevTrack = () => {
    if (player) player.previousVideo();
  };

  const toggleShuffle = () => {
    const newShuffle = !isShuffle;
    setIsShuffle(newShuffle);
    if (player) {
      player.setShuffle(newShuffle);
    }
  };

  const selectPlaylist = (playlist: typeof PLAYLISTS[0]) => {
    setCurrentPlaylist(playlist);
    setShowPlaylists(false);
    setPlaylistTracks([]); // Clear the queue visually while it loads
    setTrackInfo({ title: 'Loading...', artist: 'Fetching tracks...', videoId: '' });
    setIsPlaying(false);
    // Note: We don't manually call player.loadPlaylist anymore.
    // Changing currentPlaylist.id forces the YouTube component to completely remount with the new playlist ID!
  };

  return (
    <div className={`relative w-full h-full flex overflow-hidden transition-colors duration-300 ${isLight ? 'bg-slate-100/80 text-slate-900' : 'bg-slate-900/80 text-white'} backdrop-blur-xl`}>
      {/* Hidden Player - Non-zero dimensions are CRITICAL to prevent YouTube anti-fraud pausing */}
      <div className="absolute opacity-0 pointer-events-none w-48 h-48 z-[-10] overflow-hidden">
        <YouTube key={currentPlaylist.id} opts={opts} onReady={onReady} onStateChange={onStateChange} onError={onError} />
      </div>

      {/* Main Player Area */}
      <div className="flex-1 w-full min-w-0 flex flex-col items-center justify-center p-4 sm:p-8 relative overflow-hidden">

        {/* Top bar with Toggle Playlist */}
        <div className="absolute top-6 left-6 right-6 flex justify-between items-center z-10">
          <h2 className="text-xl font-bold tracking-tight opacity-80 flex items-center gap-2">
            <Music size={20} />
            {currentPlaylist.name}
          </h2>
          <button 
            onClick={() => { setShowPlaylists(!showPlaylists); setSidebarTab('categories'); }}
            className={`p-2 rounded-full transition-colors ${showPlaylists && sidebarTab === 'categories' ? 'bg-indigo-500 text-white' : 'hover:bg-slate-500/20'}`}
          >
            <ListVideo size={20} />
          </button>
        </div>

        {/* Spinning Disc */}
        <div className="relative mb-6 sm:mb-10 mt-12 sm:mt-8 flex-shrink-0">
          <div className={`w-48 h-48 sm:w-64 sm:h-64 rounded-full shadow-2xl overflow-hidden border-[6px] sm:border-8 ${isLight ? 'border-white/50' : 'border-black/50'} relative will-change-transform ${isPlaying ? 'animate-[spin_10s_linear_infinite]' : ''}`}>
            {/* Record grooves */}
            <div className="absolute inset-0 border-[30px] sm:border-[40px] border-black/80 rounded-full z-10 pointer-events-none box-border" style={{ boxShadow: 'inset 0 0 20px rgba(0,0,0,0.8)' }}></div>
            {/* Inner sticker */}
            <img src={trackInfo.videoId ? `https://i.ytimg.com/vi/${trackInfo.videoId}/hqdefault.jpg` : currentPlaylist.cover} alt="Cover" className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-24 h-24 sm:w-40 sm:h-40 rounded-full object-cover z-0" />
            {/* Center hole */}
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-3 h-3 sm:w-4 sm:h-4 bg-slate-200 rounded-full z-20 shadow-inner"></div>
          </div>
        </div>

        {/* Track Info */}
        <div className="text-center mb-6 w-full max-w-[90%] sm:max-w-[80%] px-4">
          <h3 className="text-xl sm:text-2xl font-bold truncate">{trackInfo.title}</h3>
          <p className="text-sm sm:text-lg opacity-70 truncate mt-1">{trackInfo.artist}</p>
        </div>

        {/* Progress Bar */}
        <ProgressBar player={player} duration={duration} />

        {/* Controls */}
        <div className="flex items-center gap-6">
          <button 
            onClick={toggleShuffle} 
            className={`p-3 rounded-full transition-colors ${isShuffle ? 'text-indigo-500' : 'opacity-60 hover:opacity-100 hover:bg-slate-500/10'}`}
          >
            <Shuffle size={20} />
          </button>

          <button 
            onClick={prevTrack}
            className="p-3 opacity-80 hover:opacity-100 hover:bg-slate-500/10 rounded-full transition-colors"
          >
            <SkipBack size={24} />
          </button>

          <button 
            onClick={togglePlay}
            className="p-5 bg-indigo-500 text-white hover:bg-indigo-600 rounded-full shadow-lg shadow-indigo-500/30 transition-transform active:scale-95"
          >
            {isPlaying ? <Pause size={28} fill="currentColor" /> : <Play size={28} fill="currentColor" className="ml-1" />}
          </button>

          <button 
            onClick={nextTrack}
            className="p-3 opacity-80 hover:opacity-100 hover:bg-slate-500/10 rounded-full transition-colors"
          >
            <SkipForward size={24} />
          </button>

          <div className="w-[44px]"></div> {/* Spacer to balance shuffle button */}
        </div>

      </div>

      {/* Playlists Sidebar Overlay */}
      <div className={`absolute top-0 right-0 bottom-0 w-72 backdrop-blur-3xl shadow-2xl transition-transform duration-300 z-50 flex flex-col ${showPlaylists ? 'translate-x-0' : 'translate-x-full'} ${isLight ? 'bg-white/90 border-l border-slate-200' : 'bg-slate-950/90 border-l border-slate-800'}`}>
        <div className="p-4 border-b border-slate-500/20 flex flex-col gap-3">
          <div className="flex justify-between items-center">
            <h3 className="font-bold text-lg">Menu</h3>
            <button onClick={() => setShowPlaylists(false)} className="opacity-60 hover:opacity-100">✕</button>
          </div>
          <div className="flex bg-slate-500/10 rounded-lg p-1">
            <button 
              className={`flex-1 text-sm font-medium py-1.5 rounded-md transition-colors ${sidebarTab === 'categories' ? (isLight ? 'bg-white shadow' : 'bg-slate-800 shadow') : 'opacity-70'}`}
              onClick={() => setSidebarTab('categories')}
            >Categories</button>
            <button 
              className={`flex-1 text-sm font-medium py-1.5 rounded-md transition-colors ${sidebarTab === 'queue' ? (isLight ? 'bg-white shadow' : 'bg-slate-800 shadow') : 'opacity-70'}`}
              onClick={() => setSidebarTab('queue')}
            >Queue</button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 flex flex-col gap-2">
          {sidebarTab === 'categories' && PLAYLISTS.map(list => (
            <button 
              key={list.id}
              onClick={() => selectPlaylist(list)}
              className={`flex items-center gap-4 p-3 rounded-xl transition-colors text-left ${currentPlaylist.id === list.id ? (isLight ? 'bg-indigo-100' : 'bg-indigo-900/40') : 'hover:bg-slate-500/10'}`}
            >
              <img src={list.cover} alt={list.name} className="w-12 h-12 rounded-md object-cover shadow-sm" />
              <div className="flex-1 overflow-hidden">
                <p className={`font-medium truncate ${currentPlaylist.id === list.id ? 'text-indigo-500' : ''}`}>{list.name}</p>
                <p className="text-xs opacity-60 truncate">YouTube Playlist</p>
              </div>
            </button>
          ))}

          {sidebarTab === 'queue' && playlistTracks.length > 0 && playlistTracks.map((videoId, idx) => (
            <button 
              key={`${videoId}-${idx}`}
              onClick={() => player?.playVideoAt(idx)}
              className={`flex items-center gap-3 p-2 rounded-lg transition-colors text-left ${currentTrackIndex === idx ? (isLight ? 'bg-indigo-100 text-indigo-700' : 'bg-indigo-900/40 text-indigo-300') : 'hover:bg-slate-500/10'}`}
            >
              <div className="w-6 text-xs opacity-50 text-right">{idx + 1}</div>
              <img src={`https://i.ytimg.com/vi/${videoId}/default.jpg`} alt={`Track ${idx + 1}`} className="w-10 h-10 rounded object-cover" />
              <div className="flex-1 overflow-hidden">
                <p className="font-medium text-sm truncate">Track {idx + 1}</p>
                <p className="text-[10px] opacity-60 truncate">YouTube</p>
              </div>
            </button>
          ))}

          {sidebarTab === 'queue' && playlistTracks.length === 0 && (
            <div className="flex-1 flex items-center justify-center text-sm opacity-50 text-center px-4">
              Queue is empty or still loading from YouTube...
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default MusicPlayer;

src/components/apps/QRStudio.tsx.content:
'use client';

import React, { useState, useRef } from 'react';
import { useSettingsStore } from '@/store/useSettingsStore';
import { QrCode, Download, Link, Type, Palette, Image as ImageIcon } from 'lucide-react';
import { QRCodeSVG } from 'qrcode.react';

export default function QRStudio() {
  const { themeMode, accentColor } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [qrValue, setQrValue] = useState('https://rohitpancholi.com');
  const [fgColor, setFgColor] = useState('#000000');
  const [bgColor, setBgColor] = useState('#ffffff');
  const [logoUrl, setLogoUrl] = useState<string | null>(null);

  const svgRef = useRef<SVGSVGElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDownload = () => {
    if (!svgRef.current) return;
    const svg = svgRef.current;
    const svgData = new XMLSerializer().serializeToString(svg);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();

    img.onload = () => {
      // Create padding for the downloaded image
      const padding = 40;
      canvas.width = img.width + padding * 2;
      canvas.height = img.height + padding * 2;

      if (ctx) {
        ctx.fillStyle = bgColor;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, padding, padding);

        const pngFile = canvas.toDataURL("image/png");
        const downloadLink = document.createElement("a");
        downloadLink.download = "QR_Code.png";
        downloadLink.href = `${pngFile}`;
        downloadLink.click();
      }
    };

    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setLogoUrl(url);
    }
  };

  return (
    <div className={`flex flex-col h-full w-full ${isLight ? 'bg-slate-50 text-slate-900' : 'bg-slate-900 text-white'}`}>

      {/* Header */}
      <div className={`px-6 py-4 border-b flex-shrink-0 flex items-center justify-between
        ${isLight ? 'bg-white border-slate-200' : 'bg-[#151c2c] border-white/10'}`}>
        <div className="flex items-center gap-3">
          <div className={`p-2 rounded-xl bg-gradient-to-br ${accentColor} text-white shadow-lg`}>
            <QrCode size={24} />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">QR Studio</h1>
            <p className={`text-xs ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>Custom QR Code Generator</p>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col md:flex-row overflow-hidden">

        {/* Left Side: Controls */}
        <div className={`w-full md:w-1/2 p-6 overflow-y-auto border-r ${isLight ? 'border-slate-200' : 'border-white/10'}`}>
          <div className="space-y-6">

            {/* Input Data */}
            <div>
              <label className="flex items-center gap-2 text-sm font-bold mb-2">
                <Link size={16} /> Enter URL or Text
              </label>
              <textarea 
                value={qrValue}
                onChange={(e) => setQrValue(e.target.value)}
                placeholder="https://example.com"
                className={`w-full p-4 rounded-xl border focus:ring-2 focus:outline-none transition-shadow resize-none h-32
                  ${isLight 
                    ? 'bg-white border-slate-300 focus:ring-blue-500/20' 
                    : 'bg-black/20 border-white/10 focus:ring-blue-500/50'}`}
              />
            </div>

            {/* Colors */}
            <div>
              <label className="flex items-center gap-2 text-sm font-bold mb-3">
                <Palette size={16} /> Customize Colors
              </label>
              <div className="flex gap-4">
                <div className={`flex-1 p-3 rounded-xl border flex items-center justify-between
                  ${isLight ? 'bg-white border-slate-200' : 'bg-black/20 border-white/10'}`}>
                  <span className="text-sm font-medium">Foreground</span>
                  <input 
                    type="color" 
                    value={fgColor} 
                    onChange={(e) => setFgColor(e.target.value)}
                    className="w-8 h-8 rounded cursor-pointer border-0 p-0"
                  />
                </div>
                <div className={`flex-1 p-3 rounded-xl border flex items-center justify-between
                  ${isLight ? 'bg-white border-slate-200' : 'bg-black/20 border-white/10'}`}>
                  <span className="text-sm font-medium">Background</span>
                  <input 
                    type="color" 
                    value={bgColor} 
                    onChange={(e) => setBgColor(e.target.value)}
                    className="w-8 h-8 rounded cursor-pointer border-0 p-0"
                  />
                </div>
              </div>
            </div>

            {/* Logo Upload */}
            <div>
              <label className="flex items-center gap-2 text-sm font-bold mb-3">
                <ImageIcon size={16} /> Center Logo (Optional)
              </label>
              <div className={`p-4 rounded-xl border border-dashed flex flex-col items-center justify-center gap-2
                ${isLight ? 'bg-slate-50 border-slate-300' : 'bg-white/5 border-white/20'}`}>
                {logoUrl ? (
                  <div className="flex items-center justify-between w-full">
                    <img src={logoUrl} alt="Logo" className="w-10 h-10 object-contain bg-white rounded p-1" />
                    <button 
                      onClick={() => setLogoUrl(null)}
                      className="text-xs text-red-500 hover:underline font-medium"
                    >
                      Remove Logo
                    </button>
                  </div>
                ) : (
                  <>
                    <input 
                      type="file" 
                      ref={fileInputRef} 
                      onChange={handleLogoUpload} 
                      accept="image/*" 
                      className="hidden" 
                    />
                    <button 
                      onClick={() => fileInputRef.current?.click()}
                      className={`text-sm font-medium px-4 py-2 rounded-lg transition-colors
                        ${isLight ? 'bg-slate-200 hover:bg-slate-300' : 'bg-white/10 hover:bg-white/20'}`}
                    >
                      Upload Image
                    </button>
                  </>
                )}
              </div>
            </div>

          </div>
        </div>

        {/* Right Side: Preview & Download */}
        <div className={`w-full md:w-1/2 p-8 flex flex-col items-center justify-center relative
          ${isLight ? 'bg-slate-100/50' : 'bg-black/20'}`}>

          <div className={`p-8 rounded-3xl shadow-2xl transition-all hover:scale-105 relative group
            ${isLight ? 'bg-white' : 'bg-white'}`}>
            <QRCodeSVG 
              value={qrValue || ' '} 
              size={250} 
              fgColor={fgColor} 
              bgColor={bgColor}
              level="H"
              includeMargin={false}
              ref={svgRef}
              imageSettings={logoUrl ? {
                src: logoUrl,
                x: undefined,
                y: undefined,
                height: 50,
                width: 50,
                excavate: true,
              } : undefined}
            />
          </div>

          <button 
            onClick={handleDownload}
            disabled={!qrValue}
            className={`mt-10 flex items-center gap-2 px-8 py-4 rounded-2xl font-bold text-white shadow-xl transition-all 
              ${!qrValue ? 'opacity-50 cursor-not-allowed grayscale' : 'hover:scale-105 active:scale-95 hover:shadow-2xl'} 
              bg-gradient-to-r ${accentColor}`}
          >
            <Download size={20} /> Download PNG
          </button>
        </div>

      </div>
    </div>
  );
}

src/components/apps/Settings.tsx.content:
'use client';
import { useSettingsStore, ThemeMode } from '@/store/useSettingsStore';
import { Monitor, Moon, Sun, Palette } from 'lucide-react';
import React, { useEffect, useState } from 'react';

export const ACCENT_COLORS = [
  { name: 'Midnight Purple', class: 'from-indigo-500/80 to-purple-500/80', dot: 'bg-purple-500' },
  { name: 'Emerald Hack', class: 'from-emerald-500/80 to-teal-500/80', dot: 'bg-emerald-500' },
  { name: 'Ocean Blue', class: 'from-blue-500/80 to-cyan-500/80', dot: 'bg-blue-500' },
  { name: 'Sunset Orange', class: 'from-orange-500/80 to-red-500/80', dot: 'bg-orange-500' },
  { name: 'Rose Gold', class: 'from-rose-400/80 to-pink-500/80', dot: 'bg-pink-400' },
  { name: 'Neon Pink', class: 'from-fuchsia-600/80 to-pink-600/80', dot: 'bg-fuchsia-500' },
  { name: 'Lime Green', class: 'from-lime-400/80 to-green-500/80', dot: 'bg-lime-400' },
  { name: 'Deep Crimson', class: 'from-red-600/80 to-rose-700/80', dot: 'bg-red-600' },
  { name: 'Electric Yellow', class: 'from-yellow-400/80 to-amber-500/80', dot: 'bg-yellow-400' },
  { name: 'Slate Monochrome', class: 'from-slate-500/80 to-slate-700/80', dot: 'bg-slate-500' },
];

export const WALLPAPERS = [
  { id: 'macos-sequoia', name: 'Sequoia Abstract', type: 'image', url: 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop' },
  { id: 'glass-waves', name: 'Glass Waves', type: 'image', url: 'https://images.unsplash.com/photo-1579546929518-9e396f3cc809?q=80&w=2670&auto=format&fit=crop' },
  { id: 'dark-fluid', name: 'Dark Fluid', type: 'image', url: 'https://images.unsplash.com/photo-1550684848-fac1c5b4e853?q=80&w=2670&auto=format&fit=crop' },
  { id: 'aurora', name: 'Animated Aurora', type: 'animated' },
  { id: 'vibrant-mesh', name: 'Vibrant Mesh', type: 'image', url: 'https://images.unsplash.com/photo-1614850523459-c2f4c699c52e?q=80&w=2670&auto=format&fit=crop' },
  { id: 'neon-glass', name: 'Neon Glass', type: 'image', url: 'https://images.unsplash.com/photo-1555680202-c86f0e12f086?q=80&w=2564&auto=format&fit=crop' },
  { id: 'minimal', name: 'Minimalist Black', type: 'solid', bg: 'bg-black' },
  { id: 'liquid-gold', name: 'Liquid Gold', type: 'image', url: 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?q=80&w=2564&auto=format&fit=crop' },
  { id: 'deep-space', name: 'Deep Space', type: 'image', url: 'https://images.unsplash.com/photo-1462331940025-496dfbfc7564?q=80&w=2564&auto=format&fit=crop' },
];

export default function Settings() {
  const { themeMode, accentColor, wallpaper, customColorHex, setThemeMode, setAccentColor, setCustomColorHex, setWallpaper } = useSettingsStore();
  const [mounted, setMounted] = useState(false);

  useEffect(() => setMounted(true), []);
  if (!mounted) return null;

  const isLight = themeMode === 'light';

  return (
    <div className={`flex h-full w-full relative overflow-hidden flex-col md:flex-row transition-colors ${isLight ? 'bg-slate-50/90 text-slate-900' : 'bg-slate-900/90 text-white'}`}>

      {/* Sidebar */}
      <div className={`w-full md:w-64 border-r p-6 flex flex-col shrink-0 transition-colors ${isLight ? 'border-slate-200/50 bg-white/50' : 'border-white/10 bg-black/40'}`}>
        <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
          <Monitor className="text-indigo-500" /> Settings
        </h2>

        <nav className="space-y-2 text-sm font-medium">
          <button className={`w-full text-left px-4 py-2.5 rounded-lg flex items-center gap-2 transition-all ${isLight ? 'bg-indigo-100 text-indigo-700 shadow-inner' : 'bg-white/10 text-white shadow-inner'}`}>
            <Palette size={16} /> Appearance
          </button>
        </nav>
      </div>

      {/* Main Content */}
      <div className="flex-1 p-8 overflow-y-auto">
        <h3 className="text-xl font-bold mb-6">Appearance Settings</h3>

        {/* Theme Mode */}
        <div className="mb-10">
          <p className={`text-xs font-bold uppercase tracking-wider mb-4 ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>System Theme</p>
          <div className="flex gap-4">
            <button 
              onClick={() => setThemeMode('dark')}
              className={`flex-1 p-4 rounded-xl border flex flex-col items-center gap-3 transition-all ${!isLight ? 'border-indigo-500 bg-indigo-500/10' : 'border-transparent bg-white hover:bg-slate-100 shadow-sm'}`}
            >
              <div className="w-12 h-12 rounded-full bg-slate-900 flex items-center justify-center text-white shadow-inner"><Moon size={20} /></div>
              <span className="font-semibold">Dark Mode</span>
            </button>
            <button 
              onClick={() => setThemeMode('light')}
              className={`flex-1 p-4 rounded-xl border flex flex-col items-center gap-3 transition-all ${isLight ? 'border-indigo-500 bg-indigo-50 shadow-sm' : 'border-transparent bg-white/10 hover:bg-white/20'}`}
            >
              <div className="w-12 h-12 rounded-full bg-white flex items-center justify-center text-slate-900 shadow-md"><Sun size={20} /></div>
              <span className="font-semibold">Light Mode</span>
            </button>
          </div>
        </div>

        {/* Accent Color */}
        <div className="mb-10">
          <p className={`text-xs font-bold uppercase tracking-wider mb-4 ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>Accent Color</p>
          <div className="flex flex-wrap gap-3">
            {ACCENT_COLORS.map(color => (
              <button 
                key={color.name}
                onClick={() => setAccentColor(color.class)}
                className={`px-4 py-2 rounded-full border flex items-center gap-2 transition-all 
                ${accentColor === color.class 
                  ? (isLight ? 'border-indigo-500 bg-white shadow-md scale-105' : 'border-indigo-500 bg-white/10 shadow-md scale-105') 
                  : (isLight ? 'border-transparent bg-white hover:bg-slate-100 shadow-sm' : 'border-transparent bg-black/20 hover:bg-black/30')}`}
              >
                <div className={`w-3 h-3 rounded-full ${color.dot}`}></div>
                <span className="text-sm font-medium">{color.name}</span>
              </button>
            ))}
          </div>

          <div className="mt-4 flex items-center gap-3">
            <span className={`text-sm font-medium ${isLight ? 'text-slate-600' : 'text-slate-300'}`}>Custom Color:</span>
            <input 
              type="color" 
              value={customColorHex || '#6366f1'}
              onChange={(e) => {
                setAccentColor('from-[var(--theme-accent)] to-[var(--theme-accent)]');
                setCustomColorHex(e.target.value);
              }}
              className="w-10 h-10 p-0 border-0 rounded cursor-pointer bg-transparent"
            />
            <input
               type="text"
               value={customColorHex || ''}
               placeholder="#6366f1"
               onChange={(e) => {
                 const hex = e.target.value;
                 setCustomColorHex(hex);
                 if (/^#[0-9A-F]{6}$/i.test(hex) || /^#[0-9A-F]{3}$/i.test(hex)) {
                   setAccentColor('from-[var(--theme-accent)] to-[var(--theme-accent)]');
                 }
               }}
               className={`px-3 py-2 border rounded-lg text-sm w-28 outline-none transition-colors uppercase font-mono
                ${isLight ? 'bg-white border-slate-200 focus:border-indigo-500' : 'bg-black/20 border-white/10 focus:border-indigo-500'}`}
            />
          </div>
        </div>

        {/* Wallpapers */}
        <div>
          <div className="flex justify-between items-center mb-4">
            <p className={`text-xs font-bold uppercase tracking-wider ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>Desktop Wallpaper</p>
            <label className="cursor-pointer text-xs font-bold bg-indigo-500 text-white px-3 py-1.5 rounded hover:bg-indigo-600 transition-colors shadow-sm">
              Upload Custom
              <input 
                type="file" 
                accept="image/*" 
                className="hidden" 
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) {
                    const url = URL.createObjectURL(file);
                    setWallpaper(url);
                  }
                }}
              />
            </label>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {WALLPAPERS.map(wp => (
              <button 
                key={wp.id}
                onClick={() => setWallpaper(wp.id)}
                className={`relative h-28 rounded-xl border-2 overflow-hidden flex items-end p-3 transition-all 
                ${wallpaper === wp.id 
                  ? 'border-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.5)]' 
                  : (isLight ? 'border-transparent shadow-sm' : 'border-transparent hover:border-white/30')}`}
              >
                {wp.type === 'animated' && <div className="absolute inset-0 aurora-bg opacity-50"></div>}
                {wp.type === 'image' && <img src={wp.url} alt={wp.name} className="absolute inset-0 w-full h-full object-cover opacity-50" />}
                {wp.type === 'solid' && <div className={`absolute inset-0 ${wp.bg} opacity-80`}></div>}
                <span className="relative z-10 font-semibold text-sm text-white drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] leading-tight text-left">{wp.name}</span>
              </button>
            ))}
            {wallpaper.startsWith('blob:') && (
               <div className="relative h-28 rounded-xl border-2 border-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.5)] overflow-hidden flex items-end p-3">
                 <img src={wallpaper} alt="Custom" className="absolute inset-0 w-full h-full object-cover opacity-50" />
                 <span className="relative z-10 font-semibold text-sm text-white drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] leading-tight text-left">Custom Upload</span>
               </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}

src/components/apps/Snake.tsx.content:
'use client';

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useSettingsStore } from '@/store/useSettingsStore';
import { AnimatePresence, motion } from 'framer-motion';
import { RotateCcw, Trophy } from 'lucide-react';

const GRID_SIZE = 20;
const INITIAL_SNAKE = [{ x: 10, y: 10 }, { x: 10, y: 11 }, { x: 10, y: 12 }];
const INITIAL_DIRECTION = { x: 0, y: -1 };

type Point = { x: number, y: number };

export default function Snake() {
  const { themeMode, accentColor } = useSettingsStore();
  const isLight = themeMode === 'light';

  const [snake, setSnake] = useState<Point[]>(INITIAL_SNAKE);
  const [direction, setDirection] = useState<Point>(INITIAL_DIRECTION);
  const [food, setFood] = useState<Point>({ x: 5, y: 5 });
  const [score, setScore] = useState(0);
  const [bestScore, setBestScore] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const directionRef = useRef(direction);

  useEffect(() => {
    directionRef.current = direction;
  }, [direction]);

  useEffect(() => {
    const savedBest = localStorage.getItem('snake-best');
    if (savedBest) setBestScore(parseInt(savedBest, 10));
    generateFood(INITIAL_SNAKE);
  }, []);

  useEffect(() => {
    if (score > bestScore) {
      setBestScore(score);
      localStorage.setItem('snake-best', score.toString());
    }
  }, [score, bestScore]);

  const generateFood = (currentSnake: Point[]) => {
    let newFood: Point;
    while (true) {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
      // Make sure food is not on snake
      if (!currentSnake.some(segment => segment.x === newFood.x && segment.y === newFood.y)) {
        break;
      }
    }
    setFood(newFood);
  };

  const resetGame = () => {
    setSnake(INITIAL_SNAKE);
    setDirection(INITIAL_DIRECTION);
    directionRef.current = INITIAL_DIRECTION;
    setScore(0);
    setGameOver(false);
    setIsPaused(false);
    generateFood(INITIAL_SNAKE);
  };

  const moveSnake = useCallback(() => {
    if (gameOver || isPaused) return;

    setSnake(prevSnake => {
      const head = prevSnake[0];
      const newHead = {
        x: head.x + directionRef.current.x,
        y: head.y + directionRef.current.y
      };

      // Check wall collision
      if (
        newHead.x < 0 || 
        newHead.x >= GRID_SIZE || 
        newHead.y < 0 || 
        newHead.y >= GRID_SIZE
      ) {
        setGameOver(true);
        return prevSnake;
      }

      // Check self collision
      if (prevSnake.some(segment => segment.x === newHead.x && segment.y === newHead.y)) {
        setGameOver(true);
        return prevSnake;
      }

      const newSnake = [newHead, ...prevSnake];

      // Check food collision
      if (newHead.x === food.x && newHead.y === food.y) {
        setScore(s => s + 10);
        generateFood(newSnake);
      } else {
        newSnake.pop(); // Remove tail if no food eaten
      }

      return newSnake;
    });
  }, [food, gameOver, isPaused]);

  // Game Loop
  useEffect(() => {
    const speed = Math.max(50, 150 - Math.floor(score / 50) * 10); // speeds up slightly as you score
    const interval = setInterval(moveSnake, speed);
    return () => clearInterval(interval);
  }, [moveSnake, score]);

  // Keyboard Controls
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
        e.preventDefault();

        const currentDir = directionRef.current;

        switch (e.key) {
          case 'ArrowUp':
            if (currentDir.y !== 1) setDirection({ x: 0, y: -1 });
            break;
          case 'ArrowDown':
            if (currentDir.y !== -1) setDirection({ x: 0, y: 1 });
            break;
          case 'ArrowLeft':
            if (currentDir.x !== 1) setDirection({ x: -1, y: 0 });
            break;
          case 'ArrowRight':
            if (currentDir.x !== -1) setDirection({ x: 1, y: 0 });
            break;
        }
      }
      if (e.key === ' ') {
        e.preventDefault();
        setIsPaused(p => !p);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Touch handlers for swipe
  const [touchStart, setTouchStart] = useState<{x: number, y: number} | null>(null);

  const handleTouchStart = (e: React.TouchEvent) => {
    setTouchStart({ x: e.touches[0].clientX, y: e.touches[0].clientY });
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (!touchStart) return;
    const touchEnd = { x: e.changedTouches[0].clientX, y: e.changedTouches[0].clientY };
    const dx = touchEnd.x - touchStart.x;
    const dy = touchEnd.y - touchStart.y;

    const currentDir = directionRef.current;

    if (Math.abs(dx) > Math.abs(dy)) { // Horizontal swipe
      if (Math.abs(dx) > 30) {
        if (dx > 0 && currentDir.x !== -1) setDirection({ x: 1, y: 0 }); // Right
        else if (dx < 0 && currentDir.x !== 1) setDirection({ x: -1, y: 0 }); // Left
      }
    } else { // Vertical swipe
      if (Math.abs(dy) > 30) {
        if (dy > 0 && currentDir.y !== -1) setDirection({ x: 0, y: 1 }); // Down
        else if (dy < 0 && currentDir.y !== 1) setDirection({ x: 0, y: -1 }); // Up
      }
    }
    setTouchStart(null);
  };

  return (
    <div className={`flex flex-col items-center justify-center h-full w-full select-none ${isLight ? 'bg-slate-50 text-slate-900' : 'bg-slate-900 text-white'}`}>
      <div className="w-full max-w-[500px] p-6 flex-1 flex flex-col justify-center">

        {/* Header */}
        <div className="flex justify-between items-end mb-6">
          <div>
            <h1 className="text-4xl font-extrabold tracking-tight">Snake</h1>
            <p className={`text-sm font-medium ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>Arcade Classic</p>
          </div>

          <div className="flex gap-3">
            <div className={`flex flex-col items-center px-4 py-1.5 rounded-lg border ${isLight ? 'bg-white border-slate-200' : 'bg-white/5 border-white/10'}`}>
              <span className="text-[10px] font-bold uppercase text-slate-500">Score</span>
              <span className="font-bold text-lg leading-none">{score}</span>
            </div>
            <div className={`flex flex-col items-center px-4 py-1.5 rounded-lg border ${isLight ? 'bg-white border-slate-200' : 'bg-white/5 border-white/10'}`}>
              <span className="text-[10px] font-bold uppercase text-slate-500 flex items-center gap-1"><Trophy size={10} className="text-yellow-500"/> Best</span>
              <span className="font-bold text-lg leading-none">{bestScore}</span>
            </div>
          </div>
        </div>

        {/* Game Board Container */}
        <div 
          className="relative aspect-square w-full rounded-xl overflow-hidden shadow-inner border border-white/10"
          style={{ backgroundColor: isLight ? '#e2e8f0' : '#0f172a' }}
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
        >
          {/* Game Grid Background (optional styling) */}
          <div 
            className="absolute inset-0 opacity-20"
            style={{ 
              backgroundImage: `linear-gradient(${isLight ? '#cbd5e1' : '#1e293b'} 1px, transparent 1px), linear-gradient(90deg, ${isLight ? '#cbd5e1' : '#1e293b'} 1px, transparent 1px)`,
              backgroundSize: `${100/GRID_SIZE}% ${100/GRID_SIZE}%`
            }}
          />

          {/* Food */}
          <div 
            className="absolute rounded-full bg-red-500 shadow-[0_0_10px_rgba(239,68,68,0.8)]"
            style={{
              width: `${100/GRID_SIZE}%`,
              height: `${100/GRID_SIZE}%`,
              left: `${(food.x / GRID_SIZE) * 100}%`,
              top: `${(food.y / GRID_SIZE) * 100}%`,
              transform: 'scale(0.8)'
            }}
          />

          {/* Snake */}
          {snake.map((segment, idx) => {
            const isHead = idx === 0;
            return (
              <div 
                key={`${segment.x}-${segment.y}-${idx}`}
                className={`absolute rounded-sm ${isHead ? `bg-gradient-to-br z-10 ${accentColor}` : 'bg-[var(--theme-accent,currentColor)] opacity-80'}`}
                style={{
                  width: `${100/GRID_SIZE}%`,
                  height: `${100/GRID_SIZE}%`,
                  left: `${(segment.x / GRID_SIZE) * 100}%`,
                  top: `${(segment.y / GRID_SIZE) * 100}%`,
                  transform: isHead ? 'scale(1.05)' : 'scale(0.9)',
                  transition: 'left 0.1s linear, top 0.1s linear' // smooth movement
                }}
              />
            );
          })}

          {/* Overlays */}
          <AnimatePresence>
            {gameOver && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute inset-0 z-50 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm"
              >
                <h2 className="text-4xl font-extrabold text-white mb-6 drop-shadow-lg">Game Over!</h2>
                <button 
                  onClick={resetGame}
                  className={`px-6 py-3 rounded-xl font-bold text-lg shadow-lg hover:scale-105 active:scale-95 flex items-center gap-2
                    ${isLight ? 'bg-white text-slate-900' : 'bg-slate-800 text-white border border-white/20'}`}
                >
                  <RotateCcw size={20} /> Play Again
                </button>
              </motion.div>
            )}

            {isPaused && !gameOver && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                className="absolute inset-0 z-40 flex items-center justify-center bg-black/40 backdrop-blur-sm"
              >
                <h2 className="text-3xl font-bold text-white tracking-widest uppercase">Paused</h2>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Instructions */}
        <p className={`mt-6 text-xs text-center font-medium ${isLight ? 'text-slate-500' : 'text-slate-400'}`}>
          Use <strong className={isLight ? 'text-slate-700' : 'text-slate-200'}>Arrow Keys</strong> or <strong className={isLight ? 'text-slate-700' : 'text-slate-200'}>Swipe</strong> to move. Press <strong className={isLight ? 'text-slate-700' : 'text-slate-200'}>Space</strong> to pause.
        </p>

      </div>
    </div>
  );
}

